# ============================================================

import requests
import pandas as pd
import numpy as np

# ------------------------------------------------------------
# LEAGUE CONFIG
# ------------------------------------------------------------

CURRENT_LEAGUE_ID = "1311997831757705216"

# Weeks 15+ are postseason in every season so far.
# We will still read the actual setting from Sleeper.
MAX_WEEK_TO_PULL = 18

# ------------------------------------------------------------
# HISTORICAL CORRECTIONS
# ------------------------------------------------------------

# Sleeper's final 2024 ownership state does not reflect
# the actual historical ownership of roster 2.
#
# Matt's real Sleeper user ID:
MATT_OWNER_ID = "611706912106487808"

OWNER_ID_OVERRIDES = {
    ("2024", 2): MATT_OWNER_ID,
}

print("Setup complete.")

"""LEAGUE HISTORY"""

# ============================================================
# LEAGUE HISTORY
# Automatically walks backward through every renewed league.
# ============================================================

league_history = []

league_id = CURRENT_LEAGUE_ID

while league_id:

    url = f"https://api.sleeper.app/v1/league/{league_id}"
    league = requests.get(url).json()

    league_history.append({
        "season": str(league.get("season")),
        "league_id": str(league_id),
        "league_name": league.get("name"),
        "status": league.get("status"),
        "total_rosters": league.get("total_rosters"),
        "previous_league_id": league.get("previous_league_id"),
        "current_leg": league.get("settings", {}).get("leg"),
        "playoff_week_start": league.get("settings", {}).get(
            "playoff_week_start"
        ),
    })

    league_id = league.get("previous_league_id")


history_df = pd.DataFrame(league_history)

history_df = history_df.sort_values(
    "season"
).reset_index(drop=True)

display(history_df)

"""OWNERS + ROSTERS"""

# ============================================================
# 3. OWNERS + ROSTERS
# ============================================================
#
# PURPOSE:
# - Build the permanent franchise / historical owner database.
# - Preserve raw Sleeper ownership.
# - Apply manual historical ownership corrections.
# - Attach canonical display names.
#
# IMPORTANT LEAGUE RULE:
# roster_id = permanent franchise_id
#
# HISTORICAL 2024 CORRECTIONS:
# roster 2 -> mattboek21
# roster 9 -> nolanfm13
#
# ============================================================

import requests
import pandas as pd

# ============================================================
# 1. OWNER IDS / HISTORICAL OVERRIDES
# ============================================================

MATT_OWNER_ID = "611706912106487808"
NOLAN_OWNER_ID = "735331051261534208"

OWNER_ID_OVERRIDES = {
    ("2024", 2): MATT_OWNER_ID,
    ("2024", 9): NOLAN_OWNER_ID
}

# ============================================================
# 2. DOWNLOAD ALL LEAGUE USERS
# ============================================================

all_owner_rows = []
all_roster_rows = []

for _, season_row in history_df.iterrows():

    season = str(season_row["season"])
    league_id = str(season_row["league_id"])

    # --------------------------------------------------------
    # League users
    # --------------------------------------------------------

    users_url = (
        f"https://api.sleeper.app/v1/league/"
        f"{league_id}/users"
    )

    users_response = requests.get(
        users_url,
        timeout=30
    )
    users_response.raise_for_status()

    league_users = users_response.json() or []

    for user in league_users:

        user_id = user.get("user_id")

        metadata = (
            user.get("metadata")
            if isinstance(user.get("metadata"), dict)
            else {}
        )

        all_owner_rows.append({
            "season": season,
            "league_id": league_id,
            "user_id": (
                str(user_id)
                if user_id is not None
                else None
            ),
            "display_name": user.get("display_name"),
            "team_name": (
                metadata.get("team_name")
                or metadata.get("team_name_update")
            ),
            "avatar": user.get("avatar")
        })

    # --------------------------------------------------------
    # League rosters
    # --------------------------------------------------------

    rosters_url = (
        f"https://api.sleeper.app/v1/league/"
        f"{league_id}/rosters"
    )

    rosters_response = requests.get(
        rosters_url,
        timeout=30
    )
    rosters_response.raise_for_status()

    league_rosters = rosters_response.json() or []

    # Build same-season user lookup.
    same_season_user_lookup = {
        str(user.get("user_id")): user
        for user in league_users
        if user.get("user_id") is not None
    }

    for roster in league_rosters:

        roster_id = int(roster["roster_id"])

        raw_owner_id = roster.get("owner_id")

        raw_owner_id = (
            str(raw_owner_id)
            if raw_owner_id is not None
            else None
        )

        raw_user = (
            same_season_user_lookup.get(raw_owner_id, {})
            if raw_owner_id is not None
            else {}
        )

        raw_metadata = (
            raw_user.get("metadata")
            if isinstance(raw_user.get("metadata"), dict)
            else {}
        )

        settings = (
            roster.get("settings")
            if isinstance(roster.get("settings"), dict)
            else {}
        )

        all_roster_rows.append({
            "season": season,
            "league_id": league_id,

            "roster_id": roster_id,

            # Permanent franchise identity.
            "franchise_id": roster_id,

            # Raw Sleeper ownership.
            "raw_owner_id": raw_owner_id,

            "raw_display_name":
                raw_user.get("display_name"),

            "raw_team_name":
                (
                    raw_metadata.get("team_name")
                    or raw_metadata.get("team_name_update")
                ),

            # Sleeper season-level roster stats.
            "wins": settings.get("wins"),
            "losses": settings.get("losses"),
            "ties": settings.get("ties"),

            "points_for":
                settings.get("fpts", 0)
                + (
                    settings.get("fpts_decimal", 0)
                    / 100
                ),

            "points_against":
                settings.get("fpts_against", 0)
                + (
                    settings.get(
                        "fpts_against_decimal",
                        0
                    )
                    / 100
                ),

            "waiver_position":
                settings.get("waiver_position"),

            "total_moves":
                settings.get("total_moves"),

            "trades":
                settings.get("trades")
        })

# ============================================================
# 3. CREATE RAW OWNER + ROSTER TABLES
# ============================================================

owners_df = pd.DataFrame(all_owner_rows)

rosters_df = pd.DataFrame(all_roster_rows)

# ============================================================
# 4. BUILD GLOBAL CANONICAL USER LOOKUP
#
# A historical owner may not appear in a particular season's
# final league user list, so build names from every linked year.
# ============================================================

canonical_owner_lookup = {}

for _, row in owners_df.iterrows():

    user_id = row["user_id"]
    display_name = row["display_name"]

    if pd.isna(user_id):
        continue

    user_id = str(user_id)

    if (
        pd.notna(display_name)
        and str(display_name).strip() != ""
    ):
        canonical_owner_lookup[user_id] = str(
            display_name
        )

# Explicit known identities.
canonical_owner_lookup[MATT_OWNER_ID] = "mattboek21"
canonical_owner_lookup[NOLAN_OWNER_ID] = "nolanfm13"

# ============================================================
# 5. APPLY HISTORICAL OWNERSHIP OVERRIDES
# ============================================================

def historical_owner_for_row(row):

    key = (
        str(row["season"]),
        int(row["roster_id"])
    )

    override = OWNER_ID_OVERRIDES.get(key)

    if override is not None:
        return str(override)

    raw_owner = row["raw_owner_id"]

    if pd.isna(raw_owner):
        return None

    return str(raw_owner)


rosters_df["historical_owner_id"] = (
    rosters_df.apply(
        historical_owner_for_row,
        axis=1
    )
)

# ============================================================
# 6. ATTACH HISTORICAL DISPLAY NAME
#
# This is the name that should be used for season/game-specific
# historical records.
# ============================================================

rosters_df["display_name"] = (
    rosters_df["historical_owner_id"]
    .map(canonical_owner_lookup)
)

# ============================================================
# 7. ATTACH TEAM NAME
#
# Prefer the raw same-season team name if available.
# The owner identity is corrected separately.
# ============================================================

rosters_df["team_name"] = (
    rosters_df["raw_team_name"]
)

# ============================================================
# 8. CLEAN / STANDARDIZE
# ============================================================

rosters_df["season"] = (
    rosters_df["season"].astype(str)
)

rosters_df["roster_id"] = (
    rosters_df["roster_id"].astype(int)
)

rosters_df["franchise_id"] = (
    rosters_df["franchise_id"].astype(int)
)

for col in [
    "raw_owner_id",
    "historical_owner_id"
]:
    rosters_df[col] = (
        rosters_df[col]
        .where(rosters_df[col].notna(), None)
    )

# ============================================================
# 9. VALIDATION
# ============================================================

print("=" * 60)
print("SECTION 3 - OWNERS + ROSTERS")
print("=" * 60)

print("\nROSTER ROWS:")
print(len(rosters_df))

print("\nOWNER ROWS:")
print(len(owners_df))

print("\nROSTERS BY SEASON")

display(
    rosters_df.groupby("season")
    .size()
    .reset_index(name="rosters")
)

# ------------------------------------------------------------
# Duplicate franchise-season rows
# ------------------------------------------------------------

duplicate_rosters = rosters_df.duplicated(
    subset=["season", "roster_id"]
).sum()

print("\nDUPLICATE SEASON-ROSTER ROWS:")
print(duplicate_rosters)

assert duplicate_rosters == 0, (
    "ERROR: Duplicate season/roster rows."
)

# ------------------------------------------------------------
# Missing historical owners
# ------------------------------------------------------------

missing_historical_owners = (
    rosters_df["historical_owner_id"]
    .isna()
    .sum()
)

print("\nMISSING HISTORICAL OWNER IDS:")
print(missing_historical_owners)

assert missing_historical_owners == 0, (
    "ERROR: Missing historical owner IDs."
)

# ------------------------------------------------------------
# Missing display names
# ------------------------------------------------------------

missing_display_names = (
    rosters_df["display_name"]
    .isna()
    .sum()
)

print("\nMISSING HISTORICAL DISPLAY NAMES:")
print(missing_display_names)

assert missing_display_names == 0, (
    "ERROR: Historical owner ID has no display name."
)

# ------------------------------------------------------------
# Explicit 2024 ownership checks
# ------------------------------------------------------------

check_2024 = (
    rosters_df[
        rosters_df["season"] == "2024"
    ][
        [
            "roster_id",
            "raw_owner_id",
            "historical_owner_id",
            "raw_display_name",
            "display_name"
        ]
    ]
    .sort_values("roster_id")
    .reset_index(drop=True)
)

print("\n2024 HISTORICAL OWNERSHIP")

display(check_2024)

roster_2_2024 = rosters_df[
    (rosters_df["season"] == "2024")
    & (rosters_df["roster_id"] == 2)
].iloc[0]

assert (
    str(roster_2_2024["historical_owner_id"])
    == MATT_OWNER_ID
), (
    "ERROR: 2024 roster 2 is not mapped to Matt."
)

assert (
    str(roster_2_2024["display_name"])
    == "mattboek21"
), (
    "ERROR: 2024 roster 2 display name is not mattboek21."
)

roster_9_2024 = rosters_df[
    (rosters_df["season"] == "2024")
    & (rosters_df["roster_id"] == 9)
].iloc[0]

assert (
    str(roster_9_2024["historical_owner_id"])
    == NOLAN_OWNER_ID
), (
    "ERROR: 2024 roster 9 is not mapped to Nolan."
)

assert (
    str(roster_9_2024["display_name"])
    == "nolanfm13"
), (
    "ERROR: 2024 roster 9 display name is not nolanfm13."
)

# ------------------------------------------------------------
# Franchise IDs must equal roster IDs
# ------------------------------------------------------------

assert (
    rosters_df["franchise_id"]
    == rosters_df["roster_id"]
).all(), (
    "ERROR: franchise_id must equal roster_id."
)

# ------------------------------------------------------------
# Expected 10 franchises x 4 seasons
# ------------------------------------------------------------

expected_roster_rows = (
    history_df["total_rosters"]
    .astype(int)
    .sum()
)

print("\nEXPECTED ROSTER ROWS:")
print(expected_roster_rows)

assert len(rosters_df) == expected_roster_rows, (
    "ERROR: Roster row count does not match league history."
)

print("\n" + "=" * 60)
print("SECTION 3 VALIDATION PASSED")
print("=" * 60)

print("\nFINAL HISTORICAL ROSTER TABLE SAMPLE")

display(
    rosters_df[
        [
            "season",
            "roster_id",
            "franchise_id",
            "raw_owner_id",
            "historical_owner_id",
            "raw_display_name",
            "display_name",
            "team_name",
            "wins",
            "losses",
            "points_for"
        ]
    ]
    .sort_values(
        ["season", "roster_id"]
    )
    .head(40)
)

"""MATCHUPS + OFFICIAL WEEKS"""

# ============================================================
# 4. MATCHUPS + COMPLETED WEEK DETECTION
# ============================================================

import requests
import pandas as pd

all_matchups = []
season_info = {}

# ============================================================
# 1. DOWNLOAD MATCHUPS AND REFRESH LEAGUE STATUS
# ============================================================

for _, season_row in history_df.iterrows():

    season = str(season_row["season"])
    league_id = str(season_row["league_id"])

    league_url = (
        f"https://api.sleeper.app/v1/league/{league_id}"
    )

    response = requests.get(league_url, timeout=30)
    response.raise_for_status()

    league_data = response.json()
    settings = league_data.get("settings", {})

    status = league_data.get("status")
    current_leg = int(settings.get("leg") or 0)
    playoff_start = int(
        settings.get("playoff_week_start") or 15
    )

    # Completed seasons: all official weeks through final leg.
    #
    # Active seasons: exclude the current leg because games
    # may still be underway. Include only earlier weeks.
    #
    # This intentionally avoids depending on team scores
    # being greater than zero.

    if status == "complete":
        last_completed_week = current_leg

    else:
        last_completed_week = max(0, current_leg - 1)

    season_info[season] = {
        "status": status,
        "current_leg": current_leg,
        "last_completed_week": last_completed_week,
        "playoff_week_start": playoff_start
    }

    print(
        f"{season} | Status: {status} | "
        f"Current leg: {current_leg} | "
        f"Completed through: {last_completed_week}"
    )

    for week in range(1, MAX_WEEK_TO_PULL + 1):

        url = (
            f"https://api.sleeper.app/v1/league/"
            f"{league_id}/matchups/{week}"
        )

        response = requests.get(url, timeout=30)
        response.raise_for_status()

        matchup_data = response.json() or []

        for team in matchup_data:

            all_matchups.append({
                "season": season,
                "league_id": league_id,
                "week": int(week),

                "roster_id": int(team["roster_id"]),
                "matchup_id": team.get("matchup_id"),
                "points": team.get("points"),

                "starters": team.get("starters"),
                "players": team.get("players"),

                "starters_points": team.get(
                    "starters_points"
                ),
                "players_points": team.get(
                    "players_points"
                )
            })


# ============================================================
# 2. CREATE RAW ARCHIVE
#
# Preserve all returned weeks, including future schedules.
# ============================================================

raw_matchups_df = pd.DataFrame(all_matchups)


# ============================================================
# 3. FILTER COMPLETED WEEKS
# ============================================================

official_matchups_df = raw_matchups_df[
    raw_matchups_df.apply(
        lambda row: (
            int(row["week"]) <=
            season_info[str(row["season"])]["last_completed_week"]
        ),
        axis=1
    )
].copy()

official_matchups_df = official_matchups_df.reset_index(
    drop=True
)


# ============================================================
# 4. ATTACH HISTORICAL FRANCHISE INFORMATION
# ============================================================

matchup_owner_lookup = rosters_df[
    [
        "season",
        "roster_id",
        "franchise_id",
        "historical_owner_id",
        "display_name",
        "team_name"
    ]
].copy()

official_matchups_df = official_matchups_df.merge(
    matchup_owner_lookup,
    on=["season", "roster_id"],
    how="left",
    validate="many_to_one"
)


# ============================================================
# 5. IDENTIFY REGULAR SEASON / POSTSEASON
#
# This is classification only.
# Actual playoff eligibility is determined in Section 5.
# ============================================================

official_matchups_df["game_type_raw"] = (
    official_matchups_df.apply(
        lambda row: (
            "Regular Season"
            if int(row["week"]) <
            season_info[str(row["season"])]["playoff_week_start"]
            else "Postseason"
        ),
        axis=1
    )
)


# ============================================================
# 6. VALIDATION
# ============================================================

print("\n" + "=" * 55)
print("SECTION 4 - VALIDATION")
print("=" * 55)

print("RAW TEAM-WEEK ROWS:", len(raw_matchups_df))
print("COMPLETED TEAM-WEEK ROWS:",
      len(official_matchups_df))

print("\nCOMPLETED WEEKS BY SEASON")

display(
    official_matchups_df
    .groupby("season")["week"]
    .agg(
        first_week="min",
        last_week="max",
        weeks="nunique"
    )
    .reset_index()
)

print("\nTEAM ROWS BY SEASON")

display(
    official_matchups_df
    .groupby("season")
    .size()
    .reset_index(name="team_week_rows")
)

print("\nMISSING OWNER MAPPINGS")

missing_owners = (
    official_matchups_df["historical_owner_id"]
    .isna().sum()
)

print(missing_owners)

print("\nDUPLICATE FRANCHISE-WEEKS")

duplicates = official_matchups_df.duplicated(
    subset=["season", "week", "roster_id"]
).sum()

print(duplicates)

print("\nNULL TEAM SCORES")

null_scores = official_matchups_df["points"].isna().sum()
print(null_scores)

# Preserve raw values; flag missing scores rather than
# silently converting them to zero.

assert missing_owners == 0
assert duplicates == 0
assert null_scores == 0

print("\nSECTION 4 VALIDATION PASSED")

"""PLAYOFF ELIGIBILTY"""

# ============================================================
# 5. PLAYOFF ELIGIBILITY - CORRECTED
# ============================================================
#
# COUNT:
# - All completed regular-season games
# - First-round championship qualifiers
# - Semifinals
# - Championship
# - Third-place game
#
# EXCLUDE:
# - Fifth-place games
# - Toilet bowl and consolation bracket
# - Playoff byes
# - Future or incomplete games
#
# Supports different playoff sizes.
# ============================================================

import requests
import pandas as pd

all_bracket_rows = []
valid_playoff_games = []

# ============================================================
# 1. DOWNLOAD WINNERS BRACKETS
# ============================================================

for _, season_row in history_df.iterrows():

    season = str(season_row["season"])
    league_id = str(season_row["league_id"])

    url = (
        f"https://api.sleeper.app/v1/league/"
        f"{league_id}/winners_bracket"
    )

    response = requests.get(url, timeout=30)

    if response.status_code == 404:
        bracket = []
    else:
        response.raise_for_status()
        bracket = response.json() or []

    for game in bracket:

        all_bracket_rows.append({
            "season": season,
            "league_id": league_id,
            "round": int(game["r"]),
            "bracket_matchup_id": int(game["m"]),
            "team_1": game.get("t1"),
            "team_2": game.get("t2"),
            "winner": game.get("w"),
            "loser": game.get("l"),
            "placement": game.get("p")
        })

winners_bracket_df = pd.DataFrame(all_bracket_rows)


# ============================================================
# 2. TRACE THE CHAMPIONSHIP PATH BACKWARD
#
# Sleeper historical advancement-source fields can be null.
#
# Instead, identify which earlier winners advanced into
# the next championship-path round.
# ============================================================

for season in history_df["season"].astype(str):

    playoff_start = season_info[season]["playoff_week_start"]
    last_completed = season_info[season]["last_completed_week"]

    if last_completed < playoff_start:
        continue

    season_bracket = [
        g for g in all_bracket_rows
        if g["season"] == season
    ]

    if not season_bracket:
        raise ValueError(
            f"{season}: Missing winners bracket."
        )

    def placement_value(g):
        p = g["placement"]
        return int(p) if pd.notna(p) else None

    def game_teams(g):
        return {
            int(x)
            for x in [g["team_1"], g["team_2"]]
            if pd.notna(x)
        }

    # Locate championship and third-place games
    championship_games = [
        g for g in season_bracket
        if placement_value(g) == 1
    ]

    third_place_games = [
        g for g in season_bracket
        if placement_value(g) == 3
    ]

    if len(championship_games) != 1:
        raise ValueError(
            f"{season}: Expected exactly one championship."
        )

    if len(third_place_games) != 1:
        raise ValueError(
            f"{season}: Expected exactly one third-place game."
        )

    championship = championship_games[0]

    # Championship is the root of the path.
    championship_path = {
        int(championship["bracket_matchup_id"])
    }

    current_round = int(championship["round"])

    # Work backward, one round at a time.
    for round_number in range(current_round - 1, 0, -1):

        next_round_games = [
            g for g in season_bracket
            if (
                int(g["round"]) == round_number + 1
                and int(g["bracket_matchup_id"])
                in championship_path
            )
        ]

        advancing_teams = set()

        for g in next_round_games:
            advancing_teams.update(game_teams(g))

        candidates = [
            g for g in season_bracket
            if int(g["round"]) == round_number
        ]

        for g in candidates:

            # Placement games aren't championship qualifiers.
            if placement_value(g) is not None:
                continue

            winner = g["winner"]

            if pd.isna(winner):
                continue

            if int(winner) in advancing_teams:
                championship_path.add(
                    int(g["bracket_matchup_id"])
                )

    # ========================================================
    # 3. SELECT ELIGIBLE PLAYOFF GAMES
    # ========================================================

    for game in season_bracket:

        match_id = int(game["bracket_matchup_id"])
        placement = placement_value(game)

        if match_id == int(
            championship["bracket_matchup_id"]
        ):
            category = "Championship"

        elif match_id in championship_path:
            category = "Championship Path"

        elif placement == 3:
            category = "Third Place"

        else:
            continue

        week = (
            playoff_start + int(game["round"]) - 1
        )

        if week > last_completed:
            continue

        a = game["team_1"]
        b = game["team_2"]

        if pd.isna(a) or pd.isna(b):
            raise ValueError(
                f"{season} Week {week}: "
                "Unresolved completed playoff game."
            )

        a, b = int(a), int(b)

        # ====================================================
        # 4. VERIFY ACTUAL WEEKLY MATCHUP
        # ====================================================

        actual = official_matchups_df[
            (official_matchups_df["season"] == season) &
            (official_matchups_df["week"] == week) &
            (official_matchups_df["roster_id"].isin([a, b]))
        ]

        if len(actual) != 2:
            raise ValueError(
                f"{season} Week {week}: "
                f"Missing teams {a}, {b}"
            )

        if (
            actual["matchup_id"].isna().any()
            or actual["matchup_id"].nunique() != 1
        ):
            raise ValueError(
                f"{season} Week {week}: "
                f"Incorrect matchup pairing {a} vs {b}"
            )

        if actual["points"].isna().any():
            raise ValueError(
                f"{season} Week {week}: Missing scores."
            )

        valid_playoff_games.append({
            "season": season,
            "week": week,
            "round": int(game["round"]),
            "playoff_round": int(game["round"]),
            "roster_a": a,
            "roster_b": b,
            "playoff_category": category,
            "bracket_matchup_id": match_id
        })


# ============================================================
# 5. CREATE ELIGIBLE PLAYOFF DATABASE
# ============================================================

valid_playoff_games_df = pd.DataFrame(
    valid_playoff_games,
    columns=[
        "season",
        "week",
        "round",
        "playoff_round",
        "roster_a",
        "roster_b",
        "playoff_category",
        "bracket_matchup_id"
    ]
)

# ============================================================
# 6. BUILD RECORD-ELIGIBLE TEAM-WEEKS
# ============================================================

eligible_roster_weeks = set()

for _, game in valid_playoff_games_df.iterrows():

    for roster_id in [
        game["roster_a"],
        game["roster_b"]
    ]:

        key = (
            str(game["season"]),
            int(game["week"]),
            int(roster_id)
        )

        if key in eligible_roster_weeks:
            raise ValueError(
                f"Duplicate playoff participant: {key}"
            )

        eligible_roster_weeks.add(key)


record_matchups_df = official_matchups_df.copy()

record_matchups_df["counts_for_records"] = (
    record_matchups_df.apply(
        lambda row: (
            int(row["week"]) <
            season_info[str(row["season"])]["playoff_week_start"]
        ) or (
            str(row["season"]),
            int(row["week"]),
            int(row["roster_id"])
        ) in eligible_roster_weeks,
        axis=1
    )
)

record_matchups_df = record_matchups_df[
    record_matchups_df["counts_for_records"]
].copy().reset_index(drop=True)

record_matchups_df["game_type"] = (
    record_matchups_df.apply(
        lambda row: (
            "Regular Season"
            if int(row["week"]) <
            season_info[str(row["season"])]["playoff_week_start"]
            else "Playoffs"
        ),
        axis=1
    )
)


# ============================================================
# 7. VALIDATION
# ============================================================

print("=" * 55)
print("SECTION 5 - PLAYOFF ELIGIBILITY")
print("=" * 55)

print("\nELIGIBLE PLAYOFF GAMES BY CATEGORY")

display(
    valid_playoff_games_df.groupby(
        ["season", "playoff_category"]
    ).size().reset_index(name="games")
)

print("\nELIGIBLE PLAYOFF GAMES BY WEEK")

display(
    valid_playoff_games_df.groupby(
        ["season", "week"]
    ).size().reset_index(name="games")
)

print("\nALL ELIGIBLE PLAYOFF PAIRINGS")

display(
    valid_playoff_games_df.sort_values(
        ["season", "week", "bracket_matchup_id"]
    )
)

print("\nTOTAL RECORD-ELIGIBLE TEAM-WEEKS:")
print(len(record_matchups_df))

print("\nREGULAR SEASON / PLAYOFF TEAM-WEEKS")

display(
    record_matchups_df.groupby(
        ["season", "game_type"]
    ).size().reset_index(name="team_weeks")
)

# Every counted matchup must contain exactly two teams.
pair_sizes = record_matchups_df.groupby(
    ["season", "week", "matchup_id"]
).size()

assert (pair_sizes == 2).all()

assert len(record_matchups_df) % 2 == 0

# Explicit historical completeness checks.
expected_playoff_games = {
    "2023": 6,
    "2024": 6,
    "2025": 5
}

for season, expected in expected_playoff_games.items():

    actual_count = len(
        valid_playoff_games_df[
            valid_playoff_games_df["season"] == season
        ]
    )

    assert actual_count == expected, (
        f"{season}: Expected {expected} eligible playoff "
        f"games, found {actual_count}."
    )

print("\nSECTION 5 VALIDATION PASSED")

"""MASTER GAMES"""

# ============================================================
# 6. MASTER GAMES
#
# One row = one actual record-eligible fantasy matchup
# ============================================================

games = []

for (season, week, matchup_id), group in record_matchups_df.groupby(
    ["season", "week", "matchup_id"]
):

    # A real H2H game should contain exactly two teams
    if len(group) != 2:
        continue

    group = group.sort_values("roster_id")

    team_1 = group.iloc[0]
    team_2 = group.iloc[1]

    score_1 = float(team_1["points"])
    score_2 = float(team_2["points"])

    roster_1 = int(team_1["roster_id"])
    roster_2 = int(team_2["roster_id"])

    owner_1 = team_1["display_name"]
    owner_2 = team_2["display_name"]

    franchise_1 = int(team_1["franchise_id"])
    franchise_2 = int(team_2["franchise_id"])

    historical_owner_1 = team_1["historical_owner_id"]
    historical_owner_2 = team_2["historical_owner_id"]

    if score_1 > score_2:

        winner_roster_id = roster_1
        loser_roster_id = roster_2

        winner_franchise_id = franchise_1
        loser_franchise_id = franchise_2

        winner_owner_id = historical_owner_1
        loser_owner_id = historical_owner_2

        winner_name = owner_1
        loser_name = owner_2

        result = "Team 1"

    elif score_2 > score_1:

        winner_roster_id = roster_2
        loser_roster_id = roster_1

        winner_franchise_id = franchise_2
        loser_franchise_id = franchise_1

        winner_owner_id = historical_owner_2
        loser_owner_id = historical_owner_1

        winner_name = owner_2
        loser_name = owner_1

        result = "Team 2"

    else:

        winner_roster_id = None
        loser_roster_id = None

        winner_franchise_id = None
        loser_franchise_id = None

        winner_owner_id = None
        loser_owner_id = None

        winner_name = None
        loser_name = None

        result = "Tie"


    playoff_start = (
        season_info[str(season)]["playoff_week_start"]
    )

    if int(week) < playoff_start:
        game_type = "Regular Season"
        playoff_round = None

    else:
        game_type = "Playoffs"
        playoff_round = (
            int(week)
            - playoff_start
            + 1
        )


    games.append({
        "season": str(season),
        "week": int(week),

        "game_type": game_type,
        "playoff_round": playoff_round,

        "matchup_id": matchup_id,

        "franchise_1": franchise_1,
        "roster_1": roster_1,
        "owner_id_1": historical_owner_1,
        "owner_1": owner_1,
        "score_1": round(score_1, 2),

        "franchise_2": franchise_2,
        "roster_2": roster_2,
        "owner_id_2": historical_owner_2,
        "owner_2": owner_2,
        "score_2": round(score_2, 2),

        "winner_franchise_id": winner_franchise_id,
        "winner_roster_id": winner_roster_id,
        "winner_owner_id": winner_owner_id,
        "winner_name": winner_name,

        "loser_franchise_id": loser_franchise_id,
        "loser_roster_id": loser_roster_id,
        "loser_owner_id": loser_owner_id,
        "loser_name": loser_name,

        "margin": round(abs(score_1 - score_2), 2),
        "combined_points": round(score_1 + score_2, 2),

        "result": result
    })


games_df = pd.DataFrame(games)

games_df = games_df.sort_values(
    ["season", "week", "matchup_id"]
).reset_index(drop=True)


# ============================================================
# VALIDATION
# ============================================================

print("TOTAL RECORD-ELIGIBLE GAMES:")
print(len(games_df))

print("\nGAMES BY SEASON")

display(
    games_df
    .groupby("season")
    .size()
    .reset_index(name="games")
)

print("\nGAMES BY TYPE")

display(
    games_df
    .groupby(
        ["season", "game_type"]
    )
    .size()
    .reset_index(name="games")
)

print("\nTIES:")
print(
    (games_df["result"] == "Tie").sum()
)

print("\nMISSING OWNER NAMES:")
print(
    games_df[
        [
            "owner_1",
            "owner_2"
        ]
    ].isna().sum()
)

print("\nSAMPLE GAMES")

display(
    games_df.head(20)
)

"""MASTER PLAYER-WEEKS"""

# ============================================================
# 7. MASTER PLAYER-WEEKS - CORRECTED
# ============================================================
#
# DATASETS:
#
# player_weeks_df / raw_player_weeks_df
#   Every actual player rostered in completed weeks.
#
# eligible_player_weeks_df
#   All rostered players during record-eligible games.
#
# official_player_weeks_df
#   STARTERS ONLY during record-eligible games.
#
# bench_player_weeks_df
#   Archived bench performances.
#
# Empty Sleeper lineup slots ("0") are NOT NFL players.
#
# ============================================================

import requests
import pandas as pd


# ============================================================
# 1. BUILD OFFICIAL GAME ELIGIBILITY LOOKUP
# ============================================================

record_eligible_roster_weeks = set(
    zip(
        record_matchups_df["season"].astype(str),
        record_matchups_df["week"].astype(int),
        record_matchups_df["roster_id"].astype(int)
    )
)


# ============================================================
# 2. BUILD COMPLETE PLAYER-WEEK ARCHIVE
# ============================================================

player_week_rows = []


def normalize_player_id(value):
    """
    Convert Sleeper player IDs to consistent strings.
    Return None for empty lineup placeholders.
    """
    if value is None:
        return None

    player_id = str(value)

    if player_id in ("0", "", "None"):
        return None

    return player_id


for _, team_week in official_matchups_df.iterrows():

    season = str(team_week["season"])
    week = int(team_week["week"])
    roster_id = int(team_week["roster_id"])
    franchise_id = int(team_week["franchise_id"])

    historical_owner_id = team_week["historical_owner_id"]
    owner_name = team_week["display_name"]
    matchup_id = team_week["matchup_id"]

    players = team_week["players"]
    starters = team_week["starters"]
    players_points = team_week["players_points"]

    if not isinstance(players, list):
        players = []

    if not isinstance(starters, list):
        starters = []

    if not isinstance(players_points, dict):
        players_points = {}

    # Exclude Sleeper empty starting slots.
    starter_set = {
        player_id
        for value in starters
        if (player_id := normalize_player_id(value))
        is not None
    }

    playoff_start = (
        season_info[season]["playoff_week_start"]
    )

    game_type = (
        "Regular Season"
        if week < playoff_start
        else "Postseason"
    )

    counts_for_records = (
        season,
        week,
        roster_id
    ) in record_eligible_roster_weeks

    # Preserve the actual player list, excluding empty IDs.
    cleaned_players = [
        player_id
        for value in players
        if (player_id := normalize_player_id(value))
        is not None
    ]

    for player_id in cleaned_players:

        fantasy_points = players_points.get(player_id)

        if fantasy_points is None and player_id.isdigit():
            fantasy_points = players_points.get(int(player_id))

        is_starter = player_id in starter_set

        counts_for_player_records = (
            counts_for_records and is_starter
        )

        player_week_rows.append({
            "season": season,
            "week": week,
            "league_id": team_week["league_id"],
            "matchup_id": matchup_id,
            "game_type": game_type,

            "franchise_id": franchise_id,
            "roster_id": roster_id,

            "owner_id": historical_owner_id,
            "owner_name": owner_name,

            "player_id": player_id,
            "fantasy_points": fantasy_points,

            "is_starter": is_starter,

            # Is this a real record-eligible fantasy game?
            "counts_for_records": counts_for_records,

            # Is this a starter in a record-eligible game?
            "counts_for_player_records":
                counts_for_player_records
        })


player_weeks_df = pd.DataFrame(player_week_rows)


# ============================================================
# 3. STANDARDIZE DATA TYPES
# ============================================================

player_weeks_df["fantasy_points"] = pd.to_numeric(
    player_weeks_df["fantasy_points"],
    errors="coerce"
)

for column in [
    "is_starter",
    "counts_for_records",
    "counts_for_player_records"
]:
    player_weeks_df[column] = (
        player_weeks_df[column].astype(bool)
    )

player_weeks_df = (
    player_weeks_df
    .sort_values(
        [
            "season",
            "week",
            "roster_id",
            "is_starter",
            "player_id"
        ],
        ascending=[True, True, True, False, True]
    )
    .reset_index(drop=True)
)


# ============================================================
# 4. DOWNLOAD SLEEPER NFL PLAYER METADATA
# ============================================================

print("Downloading Sleeper NFL player database...")

players_url = "https://api.sleeper.app/v1/players/nfl"

response = requests.get(players_url, timeout=60)
response.raise_for_status()

sleeper_players = response.json() or {}

player_metadata_rows = []

for player_id, player in sleeper_players.items():

    if not isinstance(player, dict):
        continue

    player_metadata_rows.append({
        "player_id": str(player_id),

        "first_name": player.get("first_name"),
        "last_name": player.get("last_name"),
        "full_name": player.get("full_name"),

        "position": player.get("position"),
        "fantasy_positions": player.get(
            "fantasy_positions"
        ),

        # Current NFL team, not historical NFL team.
        "current_nfl_team": player.get("team"),

        "player_status": player.get("status"),
        "years_exp": player.get("years_exp"),
        "age": player.get("age")
    })

players_df = pd.DataFrame(player_metadata_rows)


# ============================================================
# 5. ATTACH PLAYER METADATA
# ============================================================

player_weeks_df = player_weeks_df.merge(
    players_df,
    on="player_id",
    how="left",
    validate="many_to_one"
)


# ============================================================
# 6. CREATE PERMANENT PLAYER DATASETS
# ============================================================

# Complete archive.
raw_player_weeks_df = (
    player_weeks_df.copy()
)

# All players rostered during eligible games.
eligible_player_weeks_df = (
    player_weeks_df[
        player_weeks_df["counts_for_records"]
    ]
    .copy()
    .reset_index(drop=True)
)

# ONLY actual starters during eligible games.
official_player_weeks_df = (
    player_weeks_df[
        player_weeks_df["counts_for_player_records"]
    ]
    .copy()
    .reset_index(drop=True)
)

# All benched players, retained for optional analysis.
bench_player_weeks_df = (
    player_weeks_df[
        ~player_weeks_df["is_starter"]
    ]
    .copy()
    .reset_index(drop=True)
)


# ============================================================
# 7. VALIDATE PLAYER RECORD ELIGIBILITY
# ============================================================

print("\n" + "=" * 60)
print("SECTION 7 - MASTER PLAYER-WEEKS VALIDATION")
print("=" * 60)

print("\nTOTAL RAW PLAYER-WEEK ROWS:")
print(len(raw_player_weeks_df))

print("\nELIGIBLE ROSTERED PLAYER-WEEKS:")
print(len(eligible_player_weeks_df))

print("\nOFFICIAL STARTER PLAYER-WEEKS:")
print(len(official_player_weeks_df))

print("\nTOTAL BENCH PLAYER-WEEKS:")
print(len(bench_player_weeks_df))

print("\nUNIQUE NFL PLAYERS:")
print(player_weeks_df["player_id"].nunique())


# No bench performances can enter official records.
assert official_player_weeks_df["is_starter"].all(), (
    "ERROR: Bench player entered official player records."
)

# No excluded team-weeks can enter official records.
assert official_player_weeks_df["counts_for_records"].all(), (
    "ERROR: Excluded game entered official player records."
)

# Both conditions must be satisfied.
assert (
    player_weeks_df["counts_for_player_records"]
    ==
    (
        player_weeks_df["counts_for_records"]
        & player_weeks_df["is_starter"]
    )
).all(), (
    "ERROR: Player record eligibility flags inconsistent."
)

# Empty lineup placeholders must not be present.
assert not player_weeks_df["player_id"].isin(
    ["0", "", "None"]
).any(), (
    "ERROR: Empty lineup placeholder found in archive."
)

# Each player appears at most once per team-week.
duplicate_count = player_weeks_df.duplicated(
    subset=[
        "season",
        "week",
        "roster_id",
        "player_id"
    ]
).sum()

assert duplicate_count == 0, (
    f"ERROR: {duplicate_count} duplicate player-weeks."
)


# ============================================================
# 8. VERIFY EVERY SLEEPER STARTING LINEUP
# ============================================================

starter_audit_rows = []

for _, team_week in official_matchups_df.iterrows():

    season = str(team_week["season"])
    week = int(team_week["week"])
    roster_id = int(team_week["roster_id"])

    starters = team_week["starters"]

    if not isinstance(starters, list):
        starters = []

    # FIX: Ignore placeholder "0" in Sleeper lineups.
    expected_starters = {
        player_id
        for value in starters
        if (player_id := normalize_player_id(value))
        is not None
    }

    actual_starters = set(
        player_weeks_df.loc[
            (player_weeks_df["season"] == season)
            & (player_weeks_df["week"] == week)
            & (player_weeks_df["roster_id"] == roster_id)
            & (player_weeks_df["is_starter"]),
            "player_id"
        ]
    )

    if expected_starters != actual_starters:

        starter_audit_rows.append({
            "season": season,
            "week": week,
            "roster_id": roster_id,

            "missing": sorted(
                expected_starters - actual_starters
            ),

            "unexpected": sorted(
                actual_starters - expected_starters
            )
        })


starter_audit_df = pd.DataFrame(
    starter_audit_rows,
    columns=[
        "season",
        "week",
        "roster_id",
        "missing",
        "unexpected"
    ]
)

print("\nSTARTER LINEUP MISMATCHES:")
print(len(starter_audit_df))

if len(starter_audit_df):
    display(starter_audit_df)

assert len(starter_audit_df) == 0, (
    "ERROR: Starter lineups do not match Sleeper."
)


# ============================================================
# 9. PLAYER DATA INTEGRITY
# ============================================================

missing_names = (
    player_weeks_df["full_name"].isna().sum()
)

missing_scores = (
    player_weeks_df["fantasy_points"].isna().sum()
)

print("\nMISSING PLAYER NAMES:", missing_names)
print("MISSING FANTASY POINT VALUES:", missing_scores)

assert missing_names == 0, (
    "ERROR: Missing NFL player names."
)

assert missing_scores == 0, (
    "ERROR: Missing player fantasy scores."
)


# ============================================================
# 10. FINAL BREAKDOWNS
# ============================================================

print("\nOFFICIAL PLAYER RECORDS BY SEASON")

display(
    official_player_weeks_df.groupby("season")
    .size()
    .reset_index(name="starter_performances")
)

print("\nOFFICIAL PLAYER RECORDS BY POSITION")

display(
    official_player_weeks_df["position"]
    .value_counts(dropna=False)
    .reset_index(name="performances")
)

print("\nPLAYER ELIGIBILITY BY SEASON")

display(
    player_weeks_df.groupby(
        ["season", "counts_for_player_records"]
    )
    .size()
    .reset_index(name="player_weeks")
)


# ============================================================
# 11. FINAL SUMMARY
# ============================================================

print("\n" + "=" * 60)
print("SECTION 7 VALIDATION PASSED")
print("=" * 60)

print("\nOFFICIAL STARTER PERFORMANCE SAMPLE")

display(
    official_player_weeks_df[
        [
            "season",
            "week",
            "owner_name",
            "full_name",
            "position",
            "fantasy_points",
            "is_starter",
            "counts_for_player_records"
        ]
    ].head(20)
)

"""PLAYER SCORE AUDIT"""

# ============================================================
# 8. PLAYER SCORE AUDIT
#
# Reconstruct every fantasy team's weekly score by summing
# starter player scores and compare against Sleeper's official
# team score.
# ============================================================

starter_totals = (
    player_weeks_df[
        player_weeks_df["is_starter"] == True
    ]
    .groupby(
        [
            "season",
            "week",
            "roster_id"
        ],
        as_index=False
    )
    .agg(
        calculated_points=(
            "fantasy_points",
            "sum"
        ),
        starter_count=(
            "player_id",
            "count"
        )
    )
)


official_scores = (
    official_matchups_df[
        [
            "season",
            "week",
            "roster_id",
            "points"
        ]
    ]
    .copy()
    .rename(
        columns={
            "points":
            "official_points"
        }
    )
)


score_audit_df = official_scores.merge(
    starter_totals,
    on=[
        "season",
        "week",
        "roster_id"
    ],
    how="left"
)


score_audit_df["difference"] = (
    score_audit_df["calculated_points"]
    - score_audit_df["official_points"]
).round(4)


score_audit_df["matches"] = (
    score_audit_df[
        "difference"
    ].abs() <= 0.01
)


print("TEAM-WEEKS CHECKED:")
print(len(score_audit_df))

print("\nMATCHES:")
print(score_audit_df["matches"].sum())

print("\nMISMATCHES:")
print(
    (~score_audit_df["matches"]).sum()
)

print("\nMATCH RATE:")
print(
    round(
        score_audit_df[
            "matches"
        ].mean() * 100,
        2
    ),
    "%"
)


print("\nMATCH RATE BY SEASON:")

audit_by_season = (
    score_audit_df
    .groupby("season")
    .agg(
        team_weeks=(
            "matches",
            "size"
        ),
        matches=(
            "matches",
            "sum"
        )
    )
    .reset_index()
)

audit_by_season["match_rate"] = (
    audit_by_season["matches"]
    / audit_by_season["team_weeks"]
    * 100
).round(2)

display(audit_by_season)


print("\nSTARTER COUNTS:")

display(
    score_audit_df[
        [
            "season",
            "starter_count"
        ]
    ]
    .value_counts()
    .reset_index(
        name="team_weeks"
    )
    .sort_values(
        [
            "season",
            "starter_count"
        ]
    )
)


print("\nMISMATCH DETAILS:")

display(
    score_audit_df[
        score_audit_df[
            "matches"
        ] == False
    ]
)

"""TEAM GAME STATISTICS"""

# ============================================================
# 9. TEAM GAME STATISTICS
# One row = one franchise's performance in one eligible game
# ============================================================

team_game_rows = []

for _, game in games_df.iterrows():

    for side in [1, 2]:

        opponent_side = 2 if side == 1 else 1

        franchise_id = int(game[f"franchise_{side}"])
        opponent_id = int(game[f"franchise_{opponent_side}"])

        points = float(game[f"score_{side}"])
        opponent_points = float(game[f"score_{opponent_side}"])

        if points > opponent_points:
            result = "W"
        elif points < opponent_points:
            result = "L"
        else:
            result = "T"

        team_game_rows.append({
            "season": str(game["season"]),
            "week": int(game["week"]),
            "game_type": game["game_type"],
            "playoff_round": game["playoff_round"],

            "franchise_id": franchise_id,
            "owner_id": game[f"owner_id_{side}"],
            "owner_name": game[f"owner_{side}"],

            "opponent_franchise_id": opponent_id,
            "opponent_owner": game[f"owner_{opponent_side}"],

            "points_for": points,
            "points_against": opponent_points,
            "point_differential": round(
                points - opponent_points, 2
            ),

            "result": result,
            "win": int(result == "W"),
            "loss": int(result == "L"),
            "tie": int(result == "T"),

            "scored_100": points >= 100,
            "scored_125": points >= 125,
            "scored_150": points >= 150,
            "scored_175": points >= 175,
            "scored_200": points >= 200,
            "scored_225": points >= 225,
            "scored_250": points >= 250
        })

team_games_df = pd.DataFrame(team_game_rows)

team_games_df = team_games_df.sort_values(
    ["season", "week", "franchise_id"]
).reset_index(drop=True)


# ============================================================
# CAREER STATISTICS
# ============================================================

career_stats_df = (
    team_games_df
    .groupby("franchise_id")
    .agg(
        games=("result", "size"),
        wins=("win", "sum"),
        losses=("loss", "sum"),
        ties=("tie", "sum"),

        total_points=("points_for", "sum"),
        points_against=("points_against", "sum"),

        average_points=("points_for", "mean"),
        highest_score=("points_for", "max"),
        lowest_score=("points_for", "min"),

        games_150=("scored_150", "sum"),
        games_175=("scored_175", "sum"),
        games_200=("scored_200", "sum"),
        games_225=("scored_225", "sum"),
        games_250=("scored_250", "sum")
    )
    .reset_index()
)

career_stats_df["win_pct"] = (
    (
        career_stats_df["wins"]
        + 0.5 * career_stats_df["ties"]
    )
    / career_stats_df["games"]
    * 100
).round(2)

career_stats_df["point_differential"] = (
    career_stats_df["total_points"]
    - career_stats_df["points_against"]
).round(2)

career_stats_df = career_stats_df.round(2)

# Get the latest known franchise display name
latest_names = (
    rosters_df
    .sort_values("season")
    .drop_duplicates("franchise_id", keep="last")
    [["franchise_id", "display_name"]]
)

career_stats_df = career_stats_df.merge(
    latest_names,
    on="franchise_id",
    how="left"
)

career_stats_df = career_stats_df.sort_values(
    ["wins", "win_pct"],
    ascending=[False, False]
).reset_index(drop=True)


# ============================================================
# VALIDATION
# ============================================================

print("TOTAL TEAM-GAME ROWS:", len(team_games_df))
