# Check starter fantasy points against official team score.
starter_score_errors = []

for _, team in official_matchups_df.iterrows():

    season = str(team["season"])
    week = int(team["week"])
    roster_id = int(team["roster_id"])

    starters = team["starters"]
    points_map = team["players_points"]

    if not isinstance(starters, list):
        starters = []

    if not isinstance(points_map, dict):
        points_map = {}

    calculated = 0.0
    missing_starters = []

    for player in starters:

        if player is None or str(player) == "0":
            continue

        player_id = str(player)

        value = points_map.get(player_id)

        if value is None and player_id.isdigit():
            value = points_map.get(int(player_id))

        if value is None:
            missing_starters.append(player_id)
        else:
            calculated += float(value)

    official_score = float(team["points"])

    if (
        missing_starters
        or abs(calculated - official_score) > 0.011
    ):
        starter_score_errors.append({
            "season": season,
            "week": week,
            "roster_id": roster_id,
            "calculated": round(calculated, 2),
            "official": official_score,
            "missing_players": missing_starters
        })


audit_check(
    "Every team score independently matches its starters",
    len(starter_score_errors) == 0,
    (
        f"{len(official_matchups_df) - len(starter_score_errors)}"
        f"/{len(official_matchups_df)} matched"
    )
)


# ============================================================
# 7. CAREER STREAK CONTINUITY AUDIT
#
# Rebuild every career streak from team_games_df.
# Season boundaries and playoff byes never break these.
# ============================================================

print("\n7. CAREER STREAK INTEGRITY")

career_streaks = streaks_df[
    streaks_df["streak_mode"] == "Career Games"
].copy()

def streak_condition(row, streak_type):

    if streak_type == "Winning":
        return int(row["win"]) == 1

    if streak_type == "Losing":
        return int(row["loss"]) == 1

    match = re.fullmatch(
        r"(\d+)\+ Points",
        str(streak_type)
    )

    if match:
        threshold = int(match.group(1))
        return float(row["points_for"]) >= threshold

    raise ValueError(
        f"Unknown career streak category: {streak_type}"
    )


streak_audit_errors = []

for (franchise, streak_type), source_group in (
    career_streaks.groupby(
        ["franchise_id", "streak_type"]
    )
):

    franchise = int(franchise)

    history = team_games_df[
        team_games_df["franchise_id"].astype(int)
        == franchise
    ].copy()

    history["_season_sort"] = (
        history["season"].astype(int)
    )

    history = history.sort_values(
        ["_season_sort", "week"]
    ).reset_index(drop=True)

    # Compute complete runs independently.
    reconstructed = []

    current_run = []

    for _, game in history.iterrows():

        if streak_condition(game, streak_type):
            current_run.append(game)
        else:
            if current_run:
                reconstructed.append(current_run)
                current_run = []

    if current_run:
        reconstructed.append(current_run)

    expected = set()

    for run in reconstructed:

        first = run[0]
        last = run[-1]

        expected.add((
            int(len(run)),
            str(first["season"]),
            int(first["week"]),
            str(last["season"]),
            int(last["week"])
        ))

    observed = set()

    for _, streak in source_group.iterrows():

        observed.add((
            int(streak["length"]),
            str(streak["start_season"]),
            int(streak["start_week"]),
            str(streak["end_season"]),
            int(streak["end_week"])
        ))

    if expected != observed:

        streak_audit_errors.append({
            "franchise_id": franchise,
            "streak_type": streak_type,
            "missing": sorted(expected - observed),
            "extra": sorted(observed - expected)
        })


audit_check(
    "All career streaks match independent reconstruction",
    len(streak_audit_errors) == 0,
    streak_audit_errors[:8]
)

# Validate active career streaks.
# A career streak remains active if it includes the
# franchise's most recent record-eligible game.

last_game_lookup = {}

for franchise, history in team_games_df.groupby(
    "franchise_id"
):

    last_game = (
        history.assign(
            _season_sort=history["season"].astype(int)
        )
        .sort_values(["_season_sort", "week"])
        .iloc[-1]
    )

    last_game_lookup[int(franchise)] = (
        str(last_game["season"]),
        int(last_game["week"])
    )


active_streak_errors = []

for index, streak in career_streaks.iterrows():

    franchise = int(streak["franchise_id"])

    last_season, last_week = last_game_lookup[franchise]

    should_be_active = (
        str(streak["end_season"]) == last_season
        and int(streak["end_week"]) == last_week
    )

    if bool(streak["active"]) != should_be_active:

        active_streak_errors.append({
            "index": index,
            "franchise_id": franchise,
            "streak_type": streak["streak_type"],
            "stored_active": bool(streak["active"]),
            "expected_active": should_be_active
        })


audit_check(
    "Active career streaks agree with latest eligible games",
    len(active_streak_errors) == 0,
    active_streak_errors[:10]
)


