    grouped = (
        subset.groupby(
            [
                "player_id",
                "full_name",
                "position"
            ],
            as_index=False
        )
        .agg(
            starts=(
                "fantasy_points",
                "size"
            ),

            total_points=(
                "fantasy_points",
                "sum"
            ),

            average_points=(
                "fantasy_points",
                "mean"
            ),

            highest_score=(
                "fantasy_points",
                "max"
            ),

            lowest_score=(
                "fantasy_points",
                "min"
            ),

            seasons_played=(
                "season",
                "nunique"
            ),

            fantasy_franchises=(
                "franchise_id",
                "nunique"
            )
        )
    )

    for threshold in PLAYER_THRESHOLDS:

        counts = (
            subset.assign(
                reached=(
                    subset[
                        "fantasy_points"
                    ]
                    >= threshold
                ).astype(int)
            )
            .groupby(
                "player_id"
            )["reached"]
            .sum()
        )

        grouped[
            f"games_{threshold}"
        ] = (
            grouped["player_id"]
            .map(counts)
            .fillna(0)
            .astype(int)
        )

    grouped[
        "scoring_view"
    ] = view

    player_career_tables.append(
        grouped
    )


