record_book_parts = []


def add_records(
    source,
    category,
    metric,
    view,
    name_col,
    highest_is_best=True,
    minimum_games=0,
    completed_only=False
):

    df = source[
        source["scoring_view"]
        == view
    ].copy()

    if completed_only:
        df = df[
            df["season_complete"]
        ]

    if minimum_games:

        if "games" in df.columns:
            sample_col = "games"
        else:
            sample_col = "starts"

        df = df[
            df[sample_col]
            >= minimum_games
        ]

    if df.empty:
        return

    # Rank against full eligible population first.
    df["rank"] = (
        df[metric]
        .rank(
            method="min",
            ascending=not highest_is_best
        )
        .astype(int)
    )

    df = (
        df.sort_values(
            [
                "rank",
                metric
            ],
            ascending=[
                True,
                not highest_is_best
            ]
        )
        .head(SCORING_TOP_N)
    )

    for _, row in df.iterrows():

        record_book_parts.append({

            "category":
                category,

            "scoring_view":
                view,

            "rank":
                int(
                    row["rank"]
                ),

            "record_holder":
                str(
                    row[name_col]
                ),

            "value":
                float(
                    row[metric]
                ),

            "season":
                (
                    str(
                        row["season"]
                    )
                    if "season"
                    in row.index
                    else None
                ),

            "franchise_id":
                (
                    int(
                        row[
                            "franchise_id"
                        ]
                    )
                    if "franchise_id"
                    in row.index
                    else None
                ),

            "player_id":
                (
                    str(
                        row[
                            "player_id"
                        ]
                    )
                    if "player_id"
                    in row.index
                    else None
                ),

            "metric":
                metric
        })


