"""Section 14"""

# ============================================================
# 14. WIN / LOSS, ALL-PLAY, STANDINGS & PLAYOFF RECORDS
# ============================================================
#
# OFFICIAL DEFINITIONS
#
# CAREER RECORD:
# - All record-eligible games
# - Regular season + eligible playoffs
#
# REGULAR-SEASON RECORD:
# - Regular season only
#
# SINGLE-SEASON RECORD:
# - Regular season only
# - Completed seasons = 14 games
#
# ALL-PLAY:
# - Regular season only
# - Each team's weekly score is compared against every
#   other team's score from the same league week
# - In a 10-team league:
#       9 All-Play decisions per week
#       126 decisions in a full 14-week season
#
# PLAYOFF RECORDS:
# - Championship path
# - Championship
# - Third-place game
# - Fifth-place excluded
# - Consolation / toilet bowl excluded
# - Byes are not games
#
# OUTPUTS
#
# standings_career_df
# standings_regular_season_career_df
# standings_playoff_career_df
# standings_seasons_df
#
# all_play_games_df
# all_play_seasons_df
# all_play_career_df
# luck_seasons_df
# luck_career_df
#
# playoff_seasons_df
# playoff_finishes_df
# playoff_career_df
# championships_df
# playoff_appearance_streaks_df
#
# standings_record_book_df
#
# ============================================================

import pandas as pd
import numpy as np


# ============================================================
# 1. HELPERS
# ============================================================

def pct(num, den):

    return np.where(
        den > 0,
        (num / den) * 100,
        np.nan
    )


def season_complete(season):

    return (
        str(
            season_info[
                str(season)
            ]["status"]
        ).lower()
        == "complete"
    )


def latest_name_lookup():

    temp = team_games_df.copy()

    temp["_season_sort"] = (
        temp["season"]
        .astype(int)
    )

    temp = (
        temp
        .sort_values(
            [
                "franchise_id",
                "_season_sort",
                "week"
            ]
        )
    )

    return (
        temp
        .drop_duplicates(
            "franchise_id",
            keep="last"
        )
        .set_index(
            "franchise_id"
        )["owner_name"]
        .to_dict()
    )


latest_owner_name = (
    latest_name_lookup()
)


# ============================================================
# 2. MASTER REGULAR / PLAYOFF SPLITS
# ============================================================

regular_team_games = (
    team_games_df[
        team_games_df["game_type"]
        == "Regular Season"
    ]
    .copy()
)

playoff_team_games = (
    team_games_df[
        team_games_df["game_type"]
        == "Playoffs"
    ]
    .copy()
)

for df in [
    team_games_df,
    regular_team_games,
    playoff_team_games
]:
    df["season"] = (
        df["season"]
        .astype(str)
    )


# ============================================================
# 3. CAREER OVERALL W/L
# ============================================================

standings_career_df = (
    team_games_df
    .groupby(
        "franchise_id",
        as_index=False
    )
    .agg(
        games=(
            "franchise_id",
            "size"
        ),

        wins=(
            "win",
            "sum"
        ),

        losses=(
            "loss",
            "sum"
        ),

        ties=(
            "tie",
            "sum"
        ),

        points_for=(
            "points_for",
            "sum"
        ),

        points_against=(
            "points_against",
            "sum"
        ),

        point_differential=(
            "point_differential",
            "sum"
        )
    )
)

standings_career_df[
    "owner_name"
] = (
    standings_career_df[
        "franchise_id"
    ]
    .map(
        latest_owner_name
    )
)

standings_career_df[
    "win_pct"
] = (
    pct(
        standings_career_df["wins"]
        + 0.5
        * standings_career_df["ties"],

        standings_career_df["games"]
    )
)

for col in [
    "points_for",
    "points_against",
    "point_differential",
    "win_pct"
]:

    standings_career_df[
        col
    ] = (
        standings_career_df[col]
        .round(2)
    )


# ============================================================
# 4. CAREER REGULAR-SEASON W/L
# ============================================================

standings_regular_season_career_df = (
    regular_team_games
    .groupby(
        "franchise_id",
        as_index=False
    )
    .agg(
        games=(
            "franchise_id",
            "size"
        ),

        wins=(
            "win",
            "sum"
        ),

        losses=(
            "loss",
            "sum"
        ),

        ties=(
            "tie",
            "sum"
        ),

        points_for=(
            "points_for",
            "sum"
        ),

        points_against=(
            "points_against",
            "sum"
        ),

        point_differential=(
            "point_differential",
            "sum"
        )
    )
)

standings_regular_season_career_df[
    "owner_name"
] = (
    standings_regular_season_career_df[
        "franchise_id"
    ]
    .map(
        latest_owner_name
    )
)

standings_regular_season_career_df[
    "win_pct"
] = (
    pct(
        standings_regular_season_career_df[
            "wins"
        ]
        +
        0.5
        *
        standings_regular_season_career_df[
            "ties"
        ],

        standings_regular_season_career_df[
            "games"
        ]
    )
)

for col in [
    "points_for",
    "points_against",
    "point_differential",
    "win_pct"
]:

    standings_regular_season_career_df[
        col
    ] = (
        standings_regular_season_career_df[
            col
        ].round(2)
    )


# ============================================================
# 5. CAREER PLAYOFF W/L
# ============================================================

standings_playoff_career_df = (
    playoff_team_games
    .groupby(
        "franchise_id",
        as_index=False
    )
    .agg(
        playoff_games=(
            "franchise_id",
            "size"
        ),

        playoff_wins=(
            "win",
            "sum"
        ),

        playoff_losses=(
            "loss",
            "sum"
        ),

        playoff_ties=(
            "tie",
            "sum"
        ),

        playoff_points_for=(
            "points_for",
            "sum"
        ),

        playoff_points_against=(
            "points_against",
            "sum"
        )
    )
)

standings_playoff_career_df[
    "owner_name"
] = (
    standings_playoff_career_df[
        "franchise_id"
    ]
    .map(
        latest_owner_name
    )
)

standings_playoff_career_df[
    "playoff_win_pct"
] = (
    pct(
        standings_playoff_career_df[
            "playoff_wins"
        ]
        +
        0.5
        *
        standings_playoff_career_df[
            "playoff_ties"
        ],

        standings_playoff_career_df[
            "playoff_games"
        ]
    )
)

standings_playoff_career_df[
    "playoff_point_differential"
] = (
    standings_playoff_career_df[
        "playoff_points_for"
    ]
    -
    standings_playoff_career_df[
        "playoff_points_against"
    ]
)

for col in [
    "playoff_points_for",
    "playoff_points_against",
    "playoff_point_differential",
    "playoff_win_pct"
]:

    standings_playoff_career_df[
        col
    ] = (
        standings_playoff_career_df[
            col
        ].round(2)
    )


# ============================================================
# 6. REGULAR-SEASON RECORDS BY SEASON
# ============================================================

standings_seasons_df = (
    regular_team_games
    .groupby(
        [
            "season",
            "franchise_id",
            "owner_name"
        ],
        as_index=False
    )
    .agg(
        games=(
            "franchise_id",
            "size"
        ),

        wins=(
            "win",
            "sum"
        ),

        losses=(
            "loss",
            "sum"
        ),

        ties=(
            "tie",
            "sum"
        ),

        points_for=(
            "points_for",
            "sum"
        ),

        points_against=(
            "points_against",
            "sum"
        ),

        point_differential=(
            "point_differential",
            "sum"
        )
    )
)

standings_seasons_df[
    "win_pct"
] = (
    pct(
        standings_seasons_df["wins"]
        +
        0.5
        *
        standings_seasons_df["ties"],

        standings_seasons_df["games"]
    )
)

standings_seasons_df[
    "season_complete"
] = (
    standings_seasons_df[
        "season"
    ].map(
        season_complete
    )
)

for col in [
    "points_for",
    "points_against",
    "point_differential",
    "win_pct"
]:

    standings_seasons_df[
        col
    ] = (
        standings_seasons_df[
            col
        ].round(2)
    )


# ============================================================
# 7. REGULAR-SEASON STANDING RANK
#
# Ranking:
# 1. Wins
# 2. Points For
#
# This is not necessarily Sleeper's historical tiebreak system.
# It is our standardized historical standings rank.
# ============================================================

season_rank_parts = []

for season, group in (
    standings_seasons_df
    .groupby(
        "season"
    )
):

    temp = (
        group
        .sort_values(
            [
                "wins",
                "points_for"
            ],
            ascending=[
                False,
                False
            ]
        )
        .reset_index(
            drop=True
        )
    )

    temp[
        "regular_season_finish"
    ] = (
        np.arange(
            1,
            len(temp) + 1
        )
    )

    season_rank_parts.append(
        temp
    )


standings_seasons_df = (
    pd.concat(
        season_rank_parts,
        ignore_index=True
    )
)


# ============================================================
# 8. ALL-PLAY WEEKLY ENGINE
#
# Each regular-season score is compared against all
# other teams in that same season/week.
#
# A tie counts as an All-Play tie.
# ============================================================

all_play_rows = []

for (
    season,
    week
), week_df in (
    regular_team_games
    .groupby(
        [
            "season",
            "week"
        ]
    )
):

    week_df = (
        week_df
        .copy()
        .reset_index(
            drop=True
        )
    )

    for _, team in (
        week_df.iterrows()
    ):

        franchise_id = int(
            team[
                "franchise_id"
            ]
        )

        score = float(
            team[
                "points_for"
            ]
        )

        opponents = (
            week_df[
                week_df[
                    "franchise_id"
                ]
                != franchise_id
            ]
        )

        all_play_wins = int(
            (
                score
                >
                opponents[
                    "points_for"
                ]
            ).sum()
        )

        all_play_losses = int(
            (
                score
                <
                opponents[
                    "points_for"
                ]
            ).sum()
        )

        all_play_ties = int(
            (
                score
                ==
                opponents[
                    "points_for"
                ]
            ).sum()
        )

        decisions = (
            all_play_wins
            +
            all_play_losses
            +
            all_play_ties
        )

        all_play_pct = (
            (
                all_play_wins
                +
                0.5
                *
                all_play_ties
            )
            /
            decisions
            *
            100
            if decisions
            else np.nan
        )

        all_play_rows.append({

            "season":
                str(season),

            "week":
                int(week),

            "franchise_id":
                franchise_id,

            "owner_name":
                team[
                    "owner_name"
                ],

            "points_for":
                score,

            "actual_result":
                team[
                    "result"
                ],

            "actual_win":
                int(
                    team["win"]
                ),

            "actual_loss":
                int(
                    team["loss"]
                ),

            "actual_tie":
                int(
                    team["tie"]
                ),

            "all_play_wins":
                all_play_wins,

            "all_play_losses":
                all_play_losses,

            "all_play_ties":
                all_play_ties,

            "all_play_decisions":
                decisions,

            "all_play_win_pct":
                round(
                    all_play_pct,
                    2
                )
        })


all_play_games_df = (
    pd.DataFrame(
        all_play_rows
    )
)


# ============================================================
# 9. ALL-PLAY BY SEASON
# ============================================================

all_play_seasons_df = (
    all_play_games_df
    .groupby(
        [
            "season",
            "franchise_id",
            "owner_name"
        ],
        as_index=False
    )
    .agg(
        weeks=(
            "week",
            "nunique"
        ),

        all_play_wins=(
            "all_play_wins",
            "sum"
        ),

        all_play_losses=(
            "all_play_losses",
            "sum"
        ),

        all_play_ties=(
            "all_play_ties",
            "sum"
        ),

        all_play_decisions=(
            "all_play_decisions",
            "sum"
        ),

        total_points=(
            "points_for",
            "sum"
        )
    )
)

all_play_seasons_df[
    "all_play_win_pct"
] = (
    pct(
        all_play_seasons_df[
            "all_play_wins"
        ]
        +
        0.5
        *
        all_play_seasons_df[
            "all_play_ties"
        ],

        all_play_seasons_df[
            "all_play_decisions"
        ]
    )
)

all_play_seasons_df[
    "season_complete"
] = (
    all_play_seasons_df[
        "season"
    ].map(
        season_complete
    )
)

all_play_seasons_df[
    "all_play_win_pct"
] = (
    all_play_seasons_df[
        "all_play_win_pct"
    ].round(2)
)

all_play_seasons_df[
    "total_points"
] = (
    all_play_seasons_df[
        "total_points"
    ].round(2)
)


# ============================================================
# 10. CAREER ALL-PLAY
# ============================================================

all_play_career_df = (
    all_play_games_df
    .groupby(
        "franchise_id",
        as_index=False
    )
    .agg(
        weeks=(
            "week",
            "size"
        ),

        all_play_wins=(
            "all_play_wins",
            "sum"
        ),

        all_play_losses=(
            "all_play_losses",
            "sum"
        ),

        all_play_ties=(
            "all_play_ties",
            "sum"
        ),

        all_play_decisions=(
            "all_play_decisions",
            "sum"
        ),

        total_points=(
            "points_for",
            "sum"
        )
    )
)

all_play_career_df[
    "owner_name"
] = (
    all_play_career_df[
        "franchise_id"
    ].map(
        latest_owner_name
    )
)

all_play_career_df[
    "all_play_win_pct"
] = (
    pct(
        all_play_career_df[
            "all_play_wins"
        ]
        +
        0.5
        *
        all_play_career_df[
            "all_play_ties"
        ],

        all_play_career_df[
            "all_play_decisions"
        ]
    )
)

all_play_career_df[
    "all_play_win_pct"
] = (
    all_play_career_df[
        "all_play_win_pct"
    ].round(2)
)

all_play_career_df[
    "total_points"
] = (
    all_play_career_df[
        "total_points"
    ].round(2)
)


# ============================================================
# 11. SEASON LUCK / RECORD VS ALL-PLAY
#
# Expected H2H wins based on weekly All-Play strength:
#
# All-Play Expected Wins
#   = All-Play Win % * H2H games
#
# Luck Wins
#   = Actual Wins - Expected Wins
#
# Positive = better actual record than scoring strength
# Negative = worse actual record than scoring strength
# ============================================================

luck_seasons_df = (
    standings_seasons_df
    .merge(
        all_play_seasons_df[
            [
                "season",
                "franchise_id",
                "all_play_wins",
                "all_play_losses",
                "all_play_ties",
                "all_play_decisions",
                "all_play_win_pct"
            ]
        ],
        on=[
            "season",
            "franchise_id"
        ],
        how="left",
        validate="one_to_one"
    )
)

luck_seasons_df[
    "expected_wins_all_play"
] = (
    (
        luck_seasons_df[
            "all_play_win_pct"
        ]
        / 100
    )
    *
    luck_seasons_df[
        "games"
    ]
)

luck_seasons_df[
    "luck_wins"
] = (
    luck_seasons_df[
        "wins"
    ]
    -
    luck_seasons_df[
        "expected_wins_all_play"
    ]
)

luck_seasons_df[
    "actual_minus_all_play_pct"
] = (
    luck_seasons_df[
        "win_pct"
    ]
    -
    luck_seasons_df[
        "all_play_win_pct"
    ]
)

for col in [
    "expected_wins_all_play",
    "luck_wins",
    "actual_minus_all_play_pct"
]:

    luck_seasons_df[
        col
    ] = (
        luck_seasons_df[
            col
        ].round(2)
    )


# ============================================================
# 12. CAREER LUCK / RECORD VS ALL-PLAY
# ============================================================

luck_career_df = (
    standings_regular_season_career_df
    .merge(
        all_play_career_df[
            [
                "franchise_id",
                "all_play_wins",
                "all_play_losses",
                "all_play_ties",
                "all_play_decisions",
                "all_play_win_pct"
            ]
        ],
        on="franchise_id",
        how="left",
        validate="one_to_one"
    )
)

luck_career_df[
    "expected_wins_all_play"
] = (
    (
        luck_career_df[
            "all_play_win_pct"
        ]
        / 100
    )
    *
    luck_career_df[
        "games"
    ]
)

luck_career_df[
    "luck_wins"
] = (
    luck_career_df[
        "wins"
    ]
    -
    luck_career_df[
        "expected_wins_all_play"
    ]
)

luck_career_df[
    "actual_minus_all_play_pct"
] = (
    luck_career_df[
        "win_pct"
    ]
    -
    luck_career_df[
        "all_play_win_pct"
    ]
)

for col in [
    "expected_wins_all_play",
    "luck_wins",
    "actual_minus_all_play_pct"
]:

    luck_career_df[
        col
    ] = (
        luck_career_df[
            col
        ].round(2)
    )


# ============================================================
# 13. PLAYOFF SEASON RECORDS
# ============================================================

playoff_seasons_df = (
    playoff_team_games
    .groupby(
        [
            "season",
            "franchise_id",
            "owner_name"
        ],
        as_index=False
    )
    .agg(
        playoff_games=(
            "franchise_id",
            "size"
        ),

        playoff_wins=(
            "win",
            "sum"
        ),

        playoff_losses=(
            "loss",
            "sum"
        ),

        playoff_points_for=(
            "points_for",
            "sum"
        ),

        playoff_points_against=(
            "points_against",
            "sum"
        )
    )
)

playoff_seasons_df[
    "playoff_win_pct"
] = (
    pct(
        playoff_seasons_df[
            "playoff_wins"
        ],
        playoff_seasons_df[
            "playoff_games"
        ]
    )
)

playoff_seasons_df[
    "playoff_point_differential"
] = (
    playoff_seasons_df[
        "playoff_points_for"
    ]
    -
    playoff_seasons_df[
        "playoff_points_against"
    ]
)

for col in [
    "playoff_points_for",
    "playoff_points_against",
    "playoff_point_differential",
    "playoff_win_pct"
]:

    playoff_seasons_df[
        col
    ] = (
        playoff_seasons_df[
            col
        ].round(2)
    )


# ============================================================
# 14. PLAYOFF FINISHES
#
# Uses Section 5 bracket categories.
#
# Champion:
# winner of Championship
#
# Runner-Up:
# loser of Championship
#
# Third:
# winner of Third Place
#
# Fourth:
# loser of Third Place
#
# Other qualified teams:
# Playoff Participant
# ============================================================

playoff_finish_rows = []

completed_playoff_seasons = (
    valid_playoff_games_df[
        "season"
    ]
    .astype(str)
    .unique()
)

for season in (
    sorted(
        completed_playoff_seasons
    )
):

    season_games = (
        valid_playoff_games_df[
            valid_playoff_games_df[
                "season"
            ].astype(str)
            == str(season)
        ]
    )

    championship_row = (
        season_games[
            season_games[
                "playoff_category"
            ]
            == "Championship"
        ]
    )

    third_row = (
        season_games[
            season_games[
                "playoff_category"
            ]
            == "Third Place"
        ]
    )

    if len(
        championship_row
    ) != 1:

        raise ValueError(
            f"{season}: Expected exactly "
            "one championship."
        )

    if len(
        third_row
    ) != 1:

        raise ValueError(
            f"{season}: Expected exactly "
            "one third-place game."
        )

    champ = (
        championship_row
        .iloc[0]
    )

    third = (
        third_row
        .iloc[0]
    )

    def find_game_result(
        season,
        week,
        roster_a,
        roster_b
    ):

        game = (
            games_df[
                (
                    games_df["season"]
                    .astype(str)
                    == str(season)
                )
                &
                (
                    games_df["week"]
                    == int(week)
                )
                &
                (
                    games_df[
                        "roster_1"
                    ].isin(
                        [
                            int(roster_a),
                            int(roster_b)
                        ]
                    )
                )
                &
                (
                    games_df[
                        "roster_2"
                    ].isin(
                        [
                            int(roster_a),
                            int(roster_b)
                        ]
                    )
                )
            ]
        )

        if len(game) != 1:
            raise ValueError(
                f"Could not uniquely find "
                f"{season} W{week} "
                f"{roster_a} vs {roster_b}"
            )

        return game.iloc[0]


    championship_game = (
        find_game_result(
            season,
            champ["week"],
            champ["roster_a"],
            champ["roster_b"]
        )
    )

    third_place_game = (
        find_game_result(
            season,
            third["week"],
            third["roster_a"],
            third["roster_b"]
        )
    )

    champion = int(
        championship_game[
            "winner_franchise_id"
        ]
    )

    runner_up = int(
        championship_game[
            "loser_franchise_id"
        ]
    )

    third_place = int(
        third_place_game[
            "winner_franchise_id"
        ]
    )

    fourth_place = int(
        third_place_game[
            "loser_franchise_id"
        ]
    )

    playoff_franchises = set()

    for _, game in (
        season_games.iterrows()
    ):

        playoff_franchises.add(
            int(
                game[
                    "roster_a"
                ]
            )
        )

        playoff_franchises.add(
            int(
                game[
                    "roster_b"
                ]
            )
        )

    finish_lookup = {
        champion:
            "Champion",

        runner_up:
            "Runner-Up",

        third_place:
            "Third Place",

        fourth_place:
            "Fourth Place"
    }

    for franchise_id in (
        sorted(
            playoff_franchises
        )
    ):

        playoff_finish_rows.append({

            "season":
                str(season),

            "franchise_id":
                franchise_id,

            "owner_name":
                rosters_df.loc[
                    (
                        rosters_df[
                            "season"
                        ]
                        == str(season)
                    )
                    &
                    (
                        rosters_df[
                            "franchise_id"
                        ]
                        == franchise_id
                    ),
                    "display_name"
                ].iloc[0],

            "playoff_finish":
                finish_lookup.get(
                    franchise_id,
                    "Playoff Participant"
                ),

            "champion":
                int(
                    franchise_id
                    == champion
                ),

            "runner_up":
                int(
                    franchise_id
                    == runner_up
                ),

            "third_place":
                int(
                    franchise_id
                    == third_place
                ),

            "fourth_place":
                int(
                    franchise_id
                    == fourth_place
                )
        })


playoff_finishes_df = (
    pd.DataFrame(
        playoff_finish_rows
    )
)


# ============================================================
# 15. CAREER PLAYOFF ACHIEVEMENTS
# ============================================================

playoff_career_df = (
    playoff_finishes_df
    .groupby(
        "franchise_id",
        as_index=False
    )
    .agg(
        playoff_appearances=(
            "season",
            "nunique"
        ),

        championships=(
            "champion",
            "sum"
        ),

        finals_appearances=(
            "runner_up",
            lambda s:
            0
        )
    )
)

# Finals = Champion + Runner-Up
finals_counts = (
    playoff_finishes_df
    .assign(
        finals_appearance=(
            playoff_finishes_df[
                "champion"
            ]
            +
            playoff_finishes_df[
                "runner_up"
            ]
        )
    )
    .groupby(
        "franchise_id"
    )[
        "finals_appearance"
    ]
    .sum()
)

third_counts = (
    playoff_finishes_df
    .groupby(
        "franchise_id"
    )[
        "third_place"
    ]
    .sum()
)

fourth_counts = (
    playoff_finishes_df
    .groupby(
        "franchise_id"
    )[
        "fourth_place"
    ]
    .sum()
)

playoff_career_df[
    "finals_appearances"
] = (
    playoff_career_df[
        "franchise_id"
    ]
    .map(
        finals_counts
    )
    .fillna(0)
    .astype(int)
)

playoff_career_df[
    "third_place_finishes"
] = (
    playoff_career_df[
        "franchise_id"
    ]
    .map(
        third_counts
    )
    .fillna(0)
    .astype(int)
)

playoff_career_df[
    "fourth_place_finishes"
] = (
    playoff_career_df[
        "franchise_id"
    ]
    .map(
        fourth_counts
    )
    .fillna(0)
    .astype(int)
)

playoff_career_df[
    "owner_name"
] = (
    playoff_career_df[
        "franchise_id"
    ].map(
        latest_owner_name
    )
)

playoff_career_df = (
    playoff_career_df
    .merge(
        standings_playoff_career_df[
            [
                "franchise_id",
                "playoff_games",
                "playoff_wins",
                "playoff_losses",
                "playoff_win_pct",
                "playoff_point_differential"
            ]
        ],
        on="franchise_id",
        how="outer",
        validate="one_to_one"
    )
)

playoff_career_df[
    "owner_name"
] = (
    playoff_career_df[
        "franchise_id"
    ].map(
        latest_owner_name
    )
)

for col in [
    "playoff_appearances",
    "championships",
    "finals_appearances",
    "third_place_finishes",
    "fourth_place_finishes",
    "playoff_games",
    "playoff_wins",
    "playoff_losses"
]:

    playoff_career_df[
        col
    ] = (
        playoff_career_df[
            col
        ]
        .fillna(0)
        .astype(int)
    )


championships_df = (
    playoff_career_df[
        [
            "franchise_id",
            "owner_name",
            "championships",
            "finals_appearances",
            "third_place_finishes",
            "playoff_appearances"
        ]
    ]
    .sort_values(
        [
            "championships",
            "finals_appearances",
            "playoff_appearances"
        ],
        ascending=[
            False,
            False,
            False
        ]
    )
    .reset_index(
        drop=True
    )
)


# ============================================================
# 16. ABOVE / BELOW .500 SEASONS - CORRECTED
# ============================================================

season_quality_df = (
    standings_seasons_df[
        standings_seasons_df[
            "season_complete"
        ]
    ]
    .copy()
)

season_quality_df[
    "above_500"
] = (
    season_quality_df[
        "win_pct"
    ] > 50
).astype(int)

season_quality_df[
    "at_500"
] = (
    season_quality_df[
        "win_pct"
    ] == 50
).astype(int)

season_quality_df[
    "below_500"
] = (
    season_quality_df[
        "win_pct"
    ] < 50
).astype(int)

season_quality_career_df = (
    season_quality_df
    .groupby(
        "franchise_id",
        as_index=False
    )
    .agg(
        completed_seasons=(
            "season",
            "nunique"
        ),

        winning_seasons=(
            "above_500",
            "sum"
        ),

        even_seasons=(
            "at_500",
            "sum"
        ),

        losing_seasons=(
            "below_500",
            "sum"
        )
    )
)

season_quality_career_df[
    "owner_name"
] = (
    season_quality_career_df[
        "franchise_id"
    ].map(
        latest_owner_name
    )
)


# ============================================================
# 17. PLAYOFF APPEARANCE STREAKS
# ============================================================

appearance_rows = []

all_completed_seasons = sorted(
    [
        str(season)
        for season in season_info
        if season_complete(
            season
        )
    ],
    key=int
)

for franchise_id in sorted(
    team_games_df[
        "franchise_id"
    ].unique()
):

    playoff_years = set(
        playoff_finishes_df.loc[
            playoff_finishes_df[
                "franchise_id"
            ]
            == franchise_id,
            "season"
        ].astype(str)
    )

    current_run = []

    for season in (
        all_completed_seasons
    ):

        if season in playoff_years:

            current_run.append(
                season
            )

        else:

            if current_run:

                appearance_rows.append({

                    "franchise_id":
                        int(
                            franchise_id
                        ),

                    "owner_name":
                        latest_owner_name[
                            int(
                                franchise_id
                            )
                        ],

                    "length":
                        len(
                            current_run
                        ),

                    "start_season":
                        current_run[0],

                    "end_season":
                        current_run[-1]
                })

                current_run = []

    if current_run:

        appearance_rows.append({

            "franchise_id":
                int(
                    franchise_id
                ),

            "owner_name":
                latest_owner_name[
                    int(
                        franchise_id
                    )
                ],

            "length":
                len(
                    current_run
                ),

            "start_season":
                current_run[0],

            "end_season":
                current_run[-1]
        })


playoff_appearance_streaks_df = (
    pd.DataFrame(
        appearance_rows
    )
)


# ============================================================
# 18. VALIDATION
# ============================================================

print(
    "\n"
    + "=" * 65
)

print(
    "SECTION 14 - WIN/LOSS, ALL-PLAY & PLAYOFF RECORDS"
)

print(
    "=" * 65
)

checks = []


def check(
    name,
    passed,
    detail=""
):

    passed = bool(
        passed
    )

    checks.append(
        (
            name,
            passed
        )
    )

    print(
        (
            "PASS"
            if passed
            else "FAIL"
        )
        +
        " | "
        +
        name
        +
        (
            f" | {detail}"
            if detail
            else ""
        )
    )


check(
    "Career games reconcile",

    int(
        standings_career_df[
            "games"
        ].sum()
    )
    ==
    len(
        team_games_df
    )
)


check(
    "Regular-season games reconcile",

    int(
        standings_regular_season_career_df[
            "games"
        ].sum()
    )
    ==
    len(
        regular_team_games
    )
)


check(
    "Playoff games reconcile",

    int(
        standings_playoff_career_df[
            "playoff_games"
        ].sum()
    )
    ==
    len(
        playoff_team_games
    )
)


check(
    "Career wins equal career losses",

    int(
        standings_career_df[
            "wins"
        ].sum()
    )
    ==
    int(
        standings_career_df[
            "losses"
        ].sum()
    )
)


check(
    "All-Play has one row per regular-season team-week",

    len(
        all_play_games_df
    )
    ==
    len(
        regular_team_games
    )
)


check(
    "Every weekly All-Play row has 9 decisions",

    (
        all_play_games_df[
            "all_play_decisions"
        ]
        == 9
    ).all()
)


completed_all_play = (
    all_play_seasons_df[
        all_play_seasons_df[
            "season_complete"
        ]
    ]
)

check(
    "Every completed All-Play season has 14 weeks",

    (
        completed_all_play[
            "weeks"
        ]
        == 14
    ).all()
)


check(
    "Every completed All-Play season has 126 decisions",

    (
        completed_all_play[
            "all_play_decisions"
        ]
        == 126
    ).all()
)


# League-wide weekly All-Play wins must equal losses.
check(
    "All-Play wins equal All-Play losses",

    int(
        all_play_games_df[
            "all_play_wins"
        ].sum()
    )
    ==
    int(
        all_play_games_df[
            "all_play_losses"
        ].sum()
    )
)


check(
    "Season luck table reconciles every season",

    len(
        luck_seasons_df
    )
    ==
    len(
        standings_seasons_df
    )
)


check(
    "Career luck has one row per franchise",

    len(
        luck_career_df
    )
    ==
    regular_team_games[
        "franchise_id"
    ].nunique()
)


check(
    "Every playoff season has one champion",

    (
        playoff_finishes_df
        .groupby(
            "season"
        )[
            "champion"
        ]
        .sum()
        == 1
    ).all()
)


check(
    "Every playoff season has one runner-up",

    (
        playoff_finishes_df
        .groupby(
            "season"
        )[
            "runner_up"
        ]
        .sum()
        == 1
    ).all()
)


check(
    "Every playoff season has one third-place finisher",

    (
        playoff_finishes_df
        .groupby(
            "season"
        )[
            "third_place"
        ]
        .sum()
        == 1
    ).all()
)


check(
    "Every playoff season has one fourth-place finisher",

    (
        playoff_finishes_df
        .groupby(
            "season"
        )[
            "fourth_place"
        ]
        .sum()
        == 1
    ).all()
)


check(
    "Championship totals equal completed playoff seasons",

    int(
        playoff_career_df[
            "championships"
        ].sum()
    )
    ==
    playoff_finishes_df[
        "season"
    ].nunique()
)


check(
    "Finals appearances equal twice completed playoff seasons",

    int(
        playoff_career_df[
            "finals_appearances"
        ].sum()
    )
    ==
    2
    *
    playoff_finishes_df[
        "season"
    ].nunique()
)


failed = [
    name
    for name, passed
    in checks
    if not passed
]

if failed:

    raise AssertionError(
        "SECTION 14 VALIDATION FAILED:\n"
        +
        "\n".join(
            failed
        )
    )


