# ============================================================
# 18. BEST PICK TABLE HELPER
#
# Ranked by drafting-franchise total starter points.
#
# Position-specific tables solve the QB scoring problem.
# ============================================================

def best_pick_table(
    source_df,
    position=None,
    role_group=None
):

    temp = (
        source_df
        .copy()
    )


    if position is not None:

        temp = (
            temp[
                temp[
                    "position"
                ]
                == position
            ]
            .copy()
        )


    if role_group is not None:

        temp = (
            temp[
                temp[
                    "role_group"
                ]
                == role_group
            ]
            .copy()
        )


    return (
        temp
        .sort_values(
            [
                "franchise_starter_points",
                "franchise_points_per_start",
                "franchise_starts",
                "pick_no"
            ],
            ascending=[
                False,
                False,
                False,
                True
            ]
        )
        .reset_index(
            drop=True
        )
    )


