"""Trades"""

# ============================================================
# 17. TRANSACTIONS AND TRADE HISTORY
# ============================================================
#
# PURPOSE
#
# Pull and preserve Sleeper transaction history across all
# linked league seasons.
#
#
# TRANSACTION TYPES
#
# - trade
# - waiver
# - free_agent
# - commissioner
# - other Sleeper transaction types if present
#
#
# DYNASTY TRADE ASSETS
#
# Players
# Draft picks
# FAAB / waiver-budget transfers
#
#
# IMPORTANT
#
# - Historical franchise identity = roster_id / franchise_id
# - Historical owner names come from season-specific rosters_df
# - Trades are analyzed separately from ordinary transactions
# - Waiver / FA activity does NOT count as trading activity
# - Draft picks are first-class assets
#
#
# OUTPUTS
#
# transactions_all_df
# transactions_df
#
# transaction_rosters_df
# transaction_player_moves_df
#
# trade_transactions_df
# trade_assets_df
# trade_sides_df
# trade_summary_df
#
# franchise_trade_summary_df
#
# waiver_transactions_df
# waiver_player_moves_df
# franchise_waiver_summary_df
#
# transaction_type_summary_df
#
# ============================================================

import requests
import pandas as pd
import numpy as np


# ============================================================
# 1. CONFIGURATION
# ============================================================

TRANSACTION_WEEKS_TO_PULL = 18


# ============================================================
# 2. HISTORICAL OWNER LOOKUP
# ============================================================

transaction_owner_lookup_df = (
    rosters_df[
        [
            "season",
            "franchise_id",
            "historical_owner_id",
            "display_name"
        ]
    ]
    .copy()
)


transaction_owner_lookup_df[
    "season"
] = (
    transaction_owner_lookup_df[
        "season"
    ]
    .astype(str)
)


transaction_owner_lookup_df[
    "franchise_id"
] = (
    transaction_owner_lookup_df[
        "franchise_id"
    ]
    .astype(int)
)


transaction_owner_lookup = {
    (
        str(row["season"]),
        int(row["franchise_id"])
    ): {
        "owner_id":
            str(row["historical_owner_id"]),

        "owner_name":
            row["display_name"]
    }

    for _, row in (
        transaction_owner_lookup_df
        .iterrows()
    )
}


def historical_owner(
    season,
    franchise_id
):

    if franchise_id is None:
        return {
            "owner_id": None,
            "owner_name": None
        }

    return transaction_owner_lookup.get(
        (
            str(season),
            int(franchise_id)
        ),
        {
            "owner_id": None,
            "owner_name": None
        }
    )


# ============================================================
# 3. PLAYER NAME LOOKUP
# ============================================================

transaction_player_lookup = {}


if "players_df" in globals():

    temp_players = (
        players_df[
            [
                "player_id",
                "full_name",
                "position",
                "current_nfl_team"
            ]
        ]
        .copy()
    )

    temp_players[
        "player_id"
    ] = (
        temp_players[
            "player_id"
        ]
        .astype(str)
    )

    transaction_player_lookup = (
        temp_players
        .set_index(
            "player_id"
        )
        .to_dict(
            orient="index"
        )
    )


def get_player_meta(
    player_id
):

    player_id = str(
        player_id
    )

    meta = (
        transaction_player_lookup
        .get(
            player_id,
            {}
        )
    )

    return {
        "player_name":
            meta.get(
                "full_name",
                player_id
            ),

        "position":
            meta.get(
                "position"
            ),

        "current_nfl_team":
            meta.get(
                "current_nfl_team"
            )
    }


# ============================================================
# 4. DOWNLOAD ALL TRANSACTIONS
# ============================================================

transaction_rows = []


for _, league_row in (
    history_df.iterrows()
):

    season = str(
        league_row[
            "season"
        ]
    )

    league_id = str(
        league_row[
            "league_id"
        ]
    )


    for week in range(
        1,
        TRANSACTION_WEEKS_TO_PULL + 1
    ):

        url = (
            f"https://api.sleeper.app/v1/"
            f"league/{league_id}/transactions/{week}"
        )

        response = requests.get(
            url,
            timeout=30
        )

        response.raise_for_status()

        transactions = (
            response.json()
            or []
        )


        for tx in transactions:

            transaction_id = str(
                tx.get(
                    "transaction_id"
                )
            )

            roster_ids = (
                tx.get(
                    "roster_ids"
                )
                if isinstance(
                    tx.get(
                        "roster_ids"
                    ),
                    list
                )
                else []
            )

            roster_ids = [
                int(x)
                for x in roster_ids
                if x is not None
            ]


            adds = (
                tx.get(
                    "adds"
                )
                if isinstance(
                    tx.get(
                        "adds"
                    ),
                    dict
                )
                else {}
            )


            drops = (
                tx.get(
                    "drops"
                )
                if isinstance(
                    tx.get(
                        "drops"
                    ),
                    dict
                )
                else {}
            )


            draft_picks = (
                tx.get(
                    "draft_picks"
                )
                if isinstance(
                    tx.get(
                        "draft_picks"
                    ),
                    list
                )
                else []
            )


            waiver_budget = (
                tx.get(
                    "waiver_budget"
                )
                if isinstance(
                    tx.get(
                        "waiver_budget"
                    ),
                    list
                )
                else []
            )


            settings = (
                tx.get(
                    "settings"
                )
                if isinstance(
                    tx.get(
                        "settings"
                    ),
                    dict
                )
                else {}
            )


            metadata = (
                tx.get(
                    "metadata"
                )
                if isinstance(
                    tx.get(
                        "metadata"
                    ),
                    dict
                )
                else {}
            )


            creator = (
                str(
                    tx.get(
                        "creator"
                    )
                )
                if tx.get(
                    "creator"
                )
                is not None
                else None
            )


            transaction_rows.append({

                "season":
                    season,

                "league_id":
                    league_id,

                "week":
                    int(
                        week
                    ),

                "transaction_id":
                    transaction_id,

                "transaction_type":
                    tx.get(
                        "type"
                    ),

                "status":
                    tx.get(
                        "status"
                    ),

                "creator_user_id":
                    creator,

                "created_timestamp":
                    tx.get(
                        "created"
                    ),

                "status_updated_timestamp":
                    tx.get(
                        "status_updated"
                    ),

                "roster_ids":
                    roster_ids,

                "roster_count":
                    len(
                        roster_ids
                    ),

                "adds":
                    adds,

                "drops":
                    drops,

                "draft_picks":
                    draft_picks,

                "waiver_budget":
                    waiver_budget,

                "settings":
                    settings,

                "metadata":
                    metadata,

                "waiver_bid":
                    settings.get(
                        "waiver_bid"
                    ),

                "priority":
                    settings.get(
                        "priority"
                    )
            })


transactions_all_df = (
    pd.DataFrame(
        transaction_rows
    )
)


if transactions_all_df.empty:

    raise ValueError(
        "No Sleeper transactions were found."
    )


# ============================================================
# 5. DEDUPLICATE TRANSACTIONS
#
# Sleeper transaction IDs should be globally unique.
# ============================================================

transactions_all_df = (
    transactions_all_df
    .sort_values(
        [
            "season",
            "week",
            "created_timestamp",
            "transaction_id"
        ]
    )
    .drop_duplicates(
        "transaction_id",
        keep="last"
    )
    .reset_index(
        drop=True
    )
)


# ============================================================
# 6. OFFICIAL COMPLETED TRANSACTIONS
#
# Preserve all raw rows in transactions_all_df.
#
# transactions_df is completed transactions only.
# ============================================================

transactions_df = (
    transactions_all_df[
        transactions_all_df[
            "status"
        ]
        .astype(str)
        .str.lower()
        .eq(
            "complete"
        )
    ]
    .copy()
    .reset_index(
        drop=True
    )
)


# ============================================================
# 7. TRANSACTION TYPE SUMMARY
# ============================================================

transaction_type_summary_df = (
    transactions_df
    .groupby(
        [
            "season",
            "transaction_type"
        ],
        as_index=False
    )
    .agg(
        transactions=(
            "transaction_id",
            "nunique"
        )
    )
)


# ============================================================
# 8. TRANSACTION PARTICIPATING ROSTERS
#
# One row per transaction-franchise.
# ============================================================

transaction_roster_rows = []


for _, tx in (
    transactions_df
    .iterrows()
):

    season = str(
        tx[
            "season"
        ]
    )


    for franchise_id in (
        tx[
            "roster_ids"
        ]
    ):

        owner = historical_owner(
            season,
            franchise_id
        )

        transaction_roster_rows.append({

            "season":
                season,

            "week":
                int(
                    tx[
                        "week"
                    ]
                ),

            "transaction_id":
                tx[
                    "transaction_id"
                ],

            "transaction_type":
                tx[
                    "transaction_type"
                ],

            "franchise_id":
                int(
                    franchise_id
                ),

            "owner_id":
                owner[
                    "owner_id"
                ],

            "owner_name":
                owner[
                    "owner_name"
                ]
        })


transaction_rosters_df = (
    pd.DataFrame(
        transaction_roster_rows
    )
)


# ============================================================
# 9. PLAYER MOVES
#
# Adds and drops are exploded separately.
# ============================================================

player_move_rows = []


for _, tx in (
    transactions_df
    .iterrows()
):

    season = str(
        tx[
            "season"
        ]
    )

    week = int(
        tx[
            "week"
        ]
    )

    transaction_id = (
        tx[
            "transaction_id"
        ]
    )

    transaction_type = (
        tx[
            "transaction_type"
        ]
    )


    # --------------------------------------------------------
    # ADDS
    # --------------------------------------------------------

    for player_id, franchise_id in (
        tx[
            "adds"
        ].items()
    ):

        if franchise_id is None:
            continue

        franchise_id = int(
            franchise_id
        )

        owner = historical_owner(
            season,
            franchise_id
        )

        player = get_player_meta(
            player_id
        )

        player_move_rows.append({

            "season":
                season,

            "week":
                week,

            "transaction_id":
                transaction_id,

            "transaction_type":
                transaction_type,

            "move_type":
                "Add",

            "player_id":
                str(
                    player_id
                ),

            "player_name":
                player[
                    "player_name"
                ],

            "position":
                player[
                    "position"
                ],

            "franchise_id":
                franchise_id,

            "owner_id":
                owner[
                    "owner_id"
                ],

            "owner_name":
                owner[
                    "owner_name"
                ]
        })


    # --------------------------------------------------------
    # DROPS
    # --------------------------------------------------------

    for player_id, franchise_id in (
        tx[
            "drops"
        ].items()
    ):

        if franchise_id is None:
            continue

        franchise_id = int(
            franchise_id
        )

        owner = historical_owner(
            season,
            franchise_id
        )

        player = get_player_meta(
            player_id
        )

        player_move_rows.append({

            "season":
                season,

            "week":
                week,

            "transaction_id":
                transaction_id,

            "transaction_type":
                transaction_type,

            "move_type":
                "Drop",

            "player_id":
                str(
                    player_id
                ),

            "player_name":
                player[
                    "player_name"
                ],

            "position":
                player[
                    "position"
                ],

            "franchise_id":
                franchise_id,

            "owner_id":
                owner[
                    "owner_id"
                ],

            "owner_name":
                owner[
                    "owner_name"
                ]
        })


transaction_player_moves_df = (
    pd.DataFrame(
        player_move_rows
    )
)


# ============================================================
# 10. TRADE TRANSACTIONS
# ============================================================

trade_transactions_df = (
    transactions_df[
        transactions_df[
            "transaction_type"
        ]
        .astype(str)
        .str.lower()
        .eq(
            "trade"
        )
    ]
    .copy()
    .reset_index(
        drop=True
    )
)


# ============================================================
# 11. TRADE ASSETS
#
# One row per asset transferred.
#
# asset_type:
#
# Player
# Draft Pick
# FAAB
#
# asset_direction is from the perspective of franchise_id:
#
# Received
# Sent
# ============================================================

trade_asset_rows = []


for _, tx in (
    trade_transactions_df
    .iterrows()
):

    season = str(
        tx[
            "season"
        ]
    )

    week = int(
        tx[
            "week"
        ]
    )

    transaction_id = (
        tx[
            "transaction_id"
        ]
    )


    # ========================================================
    # PLAYERS RECEIVED
    #
    # adds maps player_id -> receiving roster_id
    # ========================================================

    for player_id, receiving_franchise in (
        tx[
            "adds"
        ].items()
    ):

        if receiving_franchise is None:
            continue

        receiving_franchise = int(
            receiving_franchise
        )

        player = get_player_meta(
            player_id
        )

        receiver_owner = historical_owner(
            season,
            receiving_franchise
        )


        # ----------------------------------------------------
        # Find sending franchise from drops mapping
        # ----------------------------------------------------

        sending_franchise = (
            tx[
                "drops"
            ]
            .get(
                str(
                    player_id
                )
            )
        )


        if sending_franchise is None:

            sending_franchise = (
                tx[
                    "drops"
                ]
                .get(
                    player_id
                )
            )


        if sending_franchise is not None:

            sending_franchise = int(
                sending_franchise
            )

            sender_owner = historical_owner(
                season,
                sending_franchise
            )

        else:

            sender_owner = {
                "owner_id":
                    None,

                "owner_name":
                    None
            }


        # ----------------------------------------------------
        # Receiver row
        # ----------------------------------------------------

        trade_asset_rows.append({

            "season":
                season,

            "week":
                week,

            "transaction_id":
                transaction_id,

            "franchise_id":
                receiving_franchise,

            "owner_id":
                receiver_owner[
                    "owner_id"
                ],

            "owner_name":
                receiver_owner[
                    "owner_name"
                ],

            "asset_direction":
                "Received",

            "asset_type":
                "Player",

            "player_id":
                str(
                    player_id
                ),

            "player_name":
                player[
                    "player_name"
                ],

            "position":
                player[
                    "position"
                ],

            "pick_season":
                None,

            "pick_round":
                None,

            "original_pick_franchise_id":
                None,

            "counterparty_franchise_id":
                sending_franchise,

            "faab_amount":
                None
        })


        # ----------------------------------------------------
        # Sender row
        # ----------------------------------------------------

        if sending_franchise is not None:

            trade_asset_rows.append({

                "season":
                    season,

                "week":
                    week,

                "transaction_id":
                    transaction_id,

                "franchise_id":
                    sending_franchise,

                "owner_id":
                    sender_owner[
                        "owner_id"
                    ],

                "owner_name":
                    sender_owner[
                        "owner_name"
                    ],

                "asset_direction":
                    "Sent",

                "asset_type":
                    "Player",

                "player_id":
                    str(
                        player_id
                    ),

                "player_name":
                    player[
                        "player_name"
                    ],

                "position":
                    player[
                        "position"
                    ],

                "pick_season":
                    None,

                "pick_round":
                    None,

                "original_pick_franchise_id":
                    None,

                "counterparty_franchise_id":
                    receiving_franchise,

                "faab_amount":
                    None
            })


    # ========================================================
    # DRAFT PICKS
    #
    # Sleeper fields commonly include:
    #
    # season
    # round
    # roster_id          = original pick franchise
    # previous_owner_id  = sender
    # owner_id           = receiver
    # ========================================================

    for pick in (
        tx[
            "draft_picks"
        ]
    ):

        pick_season = str(
            pick.get(
                "season"
            )
        )

        pick_round = (
            int(
                pick.get(
                    "round"
                )
            )
            if pick.get(
                "round"
            )
            is not None
            else None
        )


        original_franchise = (
            int(
                pick.get(
                    "roster_id"
                )
            )
            if pick.get(
                "roster_id"
            )
            is not None
            else None
        )


        sending_franchise = (
            int(
                pick.get(
                    "previous_owner_id"
                )
            )
            if pick.get(
                "previous_owner_id"
            )
            is not None
            else None
        )


        receiving_franchise = (
            int(
                pick.get(
                    "owner_id"
                )
            )
            if pick.get(
                "owner_id"
            )
            is not None
            else None
        )


        # ----------------------------------------------------
        # RECEIVER
        # ----------------------------------------------------

        if receiving_franchise is not None:

            receiver_owner = historical_owner(
                season,
                receiving_franchise
            )

            trade_asset_rows.append({

                "season":
                    season,

                "week":
                    week,

                "transaction_id":
                    transaction_id,

                "franchise_id":
                    receiving_franchise,

                "owner_id":
                    receiver_owner[
                        "owner_id"
                    ],

                "owner_name":
                    receiver_owner[
                        "owner_name"
                    ],

                "asset_direction":
                    "Received",

                "asset_type":
                    "Draft Pick",

                "player_id":
                    None,

                "player_name":
                    None,

                "position":
                    None,

                "pick_season":
                    pick_season,

                "pick_round":
                    pick_round,

                "original_pick_franchise_id":
                    original_franchise,

                "counterparty_franchise_id":
                    sending_franchise,

                "faab_amount":
                    None
            })


        # ----------------------------------------------------
        # SENDER
        # ----------------------------------------------------

        if sending_franchise is not None:

            sender_owner = historical_owner(
                season,
                sending_franchise
            )

            trade_asset_rows.append({

                "season":
                    season,

                "week":
                    week,

                "transaction_id":
                    transaction_id,

                "franchise_id":
                    sending_franchise,

                "owner_id":
                    sender_owner[
                        "owner_id"
                    ],

                "owner_name":
                    sender_owner[
                        "owner_name"
                    ],

                "asset_direction":
                    "Sent",

                "asset_type":
                    "Draft Pick",

                "player_id":
                    None,

                "player_name":
                    None,

                "position":
                    None,

                "pick_season":
                    pick_season,

                "pick_round":
                    pick_round,

                "original_pick_franchise_id":
                    original_franchise,

                "counterparty_franchise_id":
                    receiving_franchise,

                "faab_amount":
                    None
            })


    # ========================================================
    # FAAB / WAIVER BUDGET TRANSFERS
    #
    # Sleeper convention:
    #
    # sender
    # receiver
    # amount
    # ========================================================

    for faab in (
        tx[
            "waiver_budget"
        ]
    ):

        sending_franchise = (
            int(
                faab.get(
                    "sender"
                )
            )
            if faab.get(
                "sender"
            )
            is not None
            else None
        )


        receiving_franchise = (
            int(
                faab.get(
                    "receiver"
                )
            )
            if faab.get(
                "receiver"
            )
            is not None
            else None
        )


        amount = (
            float(
                faab.get(
                    "amount"
                )
            )
            if faab.get(
                "amount"
            )
            is not None
            else 0.0
        )


        if receiving_franchise is not None:

            receiver_owner = historical_owner(
                season,
                receiving_franchise
            )

            trade_asset_rows.append({

                "season":
                    season,

                "week":
                    week,

                "transaction_id":
                    transaction_id,

                "franchise_id":
                    receiving_franchise,

                "owner_id":
                    receiver_owner[
                        "owner_id"
                    ],

                "owner_name":
                    receiver_owner[
                        "owner_name"
                    ],

                "asset_direction":
                    "Received",

                "asset_type":
                    "FAAB",

                "player_id":
                    None,

                "player_name":
                    None,

                "position":
                    None,

                "pick_season":
                    None,

                "pick_round":
                    None,

                "original_pick_franchise_id":
                    None,

                "counterparty_franchise_id":
                    sending_franchise,

                "faab_amount":
                    amount
            })


        if sending_franchise is not None:

            sender_owner = historical_owner(
                season,
                sending_franchise
            )

            trade_asset_rows.append({

                "season":
                    season,

                "week":
                    week,

                "transaction_id":
                    transaction_id,

                "franchise_id":
                    sending_franchise,

                "owner_id":
                    sender_owner[
                        "owner_id"
                    ],

                "owner_name":
                    sender_owner[
                        "owner_name"
                    ],

                "asset_direction":
                    "Sent",

                "asset_type":
                    "FAAB",

                "player_id":
                    None,

                "player_name":
                    None,

                "position":
                    None,

                "pick_season":
                    None,

                "pick_round":
                    None,

                "original_pick_franchise_id":
                    None,

                "counterparty_franchise_id":
                    receiving_franchise,

                "faab_amount":
                    amount
            })


trade_assets_df = (
    pd.DataFrame(
        trade_asset_rows
    )
)


# ============================================================
# 12. ASSET LABEL
# ============================================================

def make_trade_asset_label(
    row
):

    if (
        row[
            "asset_type"
        ]
        == "Player"
    ):

        return row[
            "player_name"
        ]


    if (
        row[
            "asset_type"
        ]
        == "Draft Pick"
    ):

        original = (
            row[
                "original_pick_franchise_id"
            ]
        )

        original_text = (
            f" (orig. F{int(original)})"
            if pd.notna(
                original
            )
            else ""
        )

        return (
            f"{row['pick_season']} "
            f"Round {int(row['pick_round'])}"
            f"{original_text}"
        )


    if (
        row[
            "asset_type"
        ]
        == "FAAB"
    ):

        return (
            f"${row['faab_amount']:g} FAAB"
        )


    return (
        row[
            "asset_type"
        ]
    )


if not trade_assets_df.empty:

    trade_assets_df[
        "asset_label"
    ] = (
        trade_assets_df
        .apply(
            make_trade_asset_label,
            axis=1
        )
    )


# ============================================================
# 13. TRADE SIDES
#
# One row per franchise per trade.
#
# received_assets
# sent_assets
# ============================================================

trade_side_rows = []


for (
    transaction_id,
    franchise_id
), group in (
    trade_assets_df
    .groupby(
        [
            "transaction_id",
            "franchise_id"
        ]
    )
):

    season = str(
        group[
            "season"
        ]
        .iloc[0]
    )

    week = int(
        group[
            "week"
        ]
        .iloc[0]
    )

    owner_name = (
        group[
            "owner_name"
        ]
        .iloc[0]
    )


    received = (
        group[
            group[
                "asset_direction"
            ]
            == "Received"
        ]
    )


    sent = (
        group[
            group[
                "asset_direction"
            ]
            == "Sent"
        ]
    )


    received_assets = list(
        received[
            "asset_label"
        ]
    )


    sent_assets = list(
        sent[
            "asset_label"
        ]
    )


    trade_side_rows.append({

        "season":
            season,

        "week":
            week,

        "transaction_id":
            transaction_id,

        "franchise_id":
            int(
                franchise_id
            ),

        "owner_name":
            owner_name,

        "assets_received":
            received_assets,

        "assets_sent":
            sent_assets,

        "received_asset_count":
            len(
                received_assets
            ),

        "sent_asset_count":
            len(
                sent_assets
            ),

        "players_received":
            int(
                (
                    received[
                        "asset_type"
                    ]
                    == "Player"
                )
                .sum()
            ),

        "players_sent":
            int(
                (
                    sent[
                        "asset_type"
                    ]
                    == "Player"
                )
                .sum()
            ),

        "picks_received":
            int(
                (
                    received[
                        "asset_type"
                    ]
                    == "Draft Pick"
                )
                .sum()
            ),

        "picks_sent":
            int(
                (
                    sent[
                        "asset_type"
                    ]
                    == "Draft Pick"
                )
                .sum()
            ),

        "faab_received":
            float(
                received.loc[
                    received[
                        "asset_type"
                    ]
                    == "FAAB",
                    "faab_amount"
                ]
                .fillna(0)
                .sum()
            ),

        "faab_sent":
            float(
                sent.loc[
                    sent[
                        "asset_type"
                    ]
                    == "FAAB",
                    "faab_amount"
                ]
                .fillna(0)
                .sum()
            )
    })


trade_sides_df = (
    pd.DataFrame(
        trade_side_rows
    )
)


# ============================================================
# 14. TRADE SUMMARY
#
# One row per trade.
# ============================================================

trade_summary_rows = []


for transaction_id, group in (
    trade_sides_df
    .groupby(
        "transaction_id"
    )
):

    group = (
        group
        .sort_values(
            "franchise_id"
        )
    )


    trade_summary_rows.append({

        "season":
            str(
                group[
                    "season"
                ]
                .iloc[0]
            ),

        "week":
            int(
                group[
                    "week"
                ]
                .iloc[0]
            ),

        "transaction_id":
            transaction_id,

        "franchises_involved":
            int(
                group[
                    "franchise_id"
                ]
                .nunique()
            ),

        "owners_involved":
            list(
                group[
                    "owner_name"
                ]
            ),

        "franchise_ids":
            list(
                group[
                    "franchise_id"
                ]
            ),

        "total_player_assets":
            int(
                group[
                    "players_received"
                ]
                .sum()
            ),

        "total_pick_assets":
            int(
                group[
                    "picks_received"
                ]
                .sum()
            ),

        "total_faab_transferred":
            float(
                group[
                    "faab_received"
                ]
                .sum()
            )
    })


trade_summary_df = (
    pd.DataFrame(
        trade_summary_rows
    )
)


