checks = []


def check(
    name,
    passed,
    detail=""
):

    passed = bool(
        passed
    )

    checks.append(
        (
            name,
            passed
        )
    )


    print(
        (
            "PASS"
            if passed
            else "FAIL"
        )
        +
        " | "
        +
        name
        +
        (
            f" | {detail}"
            if detail
            else ""
        )
    )


