# ============================================================
# 2. HELPERS
# ============================================================

def sleeper_get(
    endpoint,
    allow_404=False
):

    url = SLEEPER_BASE + endpoint

    response = requests.get(
        url,
        timeout=30
    )

    if (
        allow_404
        and
        response.status_code == 404
    ):
        return None

    response.raise_for_status()

    return response.json()


def find_column(
    df,
    candidates,
    required=True
):

    for col in candidates:

        if col in df.columns:
            return col

    if required:

        raise KeyError(
            "Could not find any of these columns:\n"
            + str(candidates)
            + "\n\nAvailable columns:\n"
            + str(list(df.columns))
        )

    return None


def normalize_int_column(
    df,
    column
):

    if column not in df.columns:
        return df

    df[column] = (
        pd.to_numeric(
            df[column],
            errors="coerce"
        )
        .astype("Int64")
    )

    return df


def sleeper_points_value(
    settings,
    whole_key,
    decimal_key
):

    settings = settings or {}

    whole = settings.get(
        whole_key,
        0
    )

    decimal = settings.get(
        decimal_key,
        0
    )

    try:

        return (
            float(whole or 0)
            +
            (
                float(decimal or 0)
                /
                100
            )
        )

    except:

        return np.nan


def parse_playoff_finish(value):
    """
    Convert various historical playoff-finish formats
    into a numeric finish when appropriate.

    Returns:
        1 = champion
        2 = runner-up
        3 = third place
        None = not a top-3 accomplishment / unknown
    """

    if value is None:
        return None

    if isinstance(
        value,
        (int, np.integer)
    ):

        value = int(value)

        if value in [1, 2, 3]:
            return value

        return None

    if isinstance(
        value,
        (float, np.floating)
    ):

        if pd.isna(value):
            return None

        value = int(value)

        if value in [1, 2, 3]:
            return value

        return None


    text = (
        str(value)
        .strip()
        .lower()
    )


    # numeric-looking string
    try:

        num = int(float(text))

        if num in [1, 2, 3]:
            return num

    except:
        pass


    if any(
        phrase in text
        for phrase in [
            "champion",
            "championship winner",
            "1st",
            "first place",
            "first"
        ]
    ):
        return 1


    if any(
        phrase in text
        for phrase in [
            "runner-up",
            "runner up",
            "2nd",
            "second place",
            "second"
        ]
    ):
        return 2


    if any(
        phrase in text
        for phrase in [
            "third place",
            "3rd",
            "third"
        ]
    ):
        return 3


    # Things like:
    # Playoff Participant
    # Semifinalist
    # Made Playoffs
    # etc.
    #
    # These are not top-3 accomplishments for this table.

    return None


