# 12. CURRENT ROSTER SNAPSHOT
# ============================================================

current_league_id = str(
    history_df
    .sort_values("season")
    .iloc[-1]["league_id"]
)


current_rosters_json = sleeper_get(
    f"/league/{current_league_id}/rosters"
)


current_roster_rows = []


for roster in current_rosters_json or []:

    franchise_id = int(
        roster.get(
            "roster_id"
        )
    )


    players = [
        str(x)
        for x in (
            roster.get(
                "players"
            )
            or []
        )
    ]


    starters_list = [
        str(x)
        for x in (
            roster.get(
                "starters"
            )
            or []
        )
    ]

    starters = set(starters_list)

    # Current lineup configuration. Sleeper's starters array follows
    # the league's non-bench roster-position order.
    current_league_meta = sleeper_get(f"/league/{current_league_id}")
    current_starter_slots = [
        pos for pos in (current_league_meta.get("roster_positions") or [])
        if pos != "BN"
    ]
    starter_slot_map = {
        player_id: (
            current_starter_slots[idx] if idx < len(current_starter_slots) else "STARTER",
            idx + 1
        )
        for idx, player_id in enumerate(starters_list)
    }


    reserve = set(
        str(x)
        for x in (
            roster.get(
                "reserve"
            )
            or []
        )
    )


    taxi = set(
        str(x)
        for x in (
            roster.get(
                "taxi"
            )
            or []
        )
    )


    for player_id in players:

        current_roster_rows.append(
            {
                "season":
                    CURRENT_YEAR,

                "league_id":
                    current_league_id,

                "franchise_id":
                    franchise_id,

                "owner_name":
                    latest_owner_name.get(
                        franchise_id
                    ),

                "player_id":
                    player_id,

                "is_starter":
                    player_id
                    in starters,

                "is_reserve":
                    player_id
                    in reserve,

                "is_taxi":
                    player_id
                    in taxi,

                "lineup_slot":
                    starter_slot_map.get(player_id, ("", ""))[0],

                "lineup_order":
                    starter_slot_map.get(player_id, ("", ""))[1]
            }
        )


current_roster_snapshot_df = pd.DataFrame(
    current_roster_rows
)


