# ============================================================

current_traded_picks_json = sleeper_get(
    f"/league/{current_league_id}/traded_picks"
)


current_league_json = sleeper_get(
    f"/league/{current_league_id}"
)


rookie_rounds = (
    current_league_json
    .get(
        "settings",
        {}
    )
    .get(
        "draft_rounds",
        DEFAULT_ROOKIE_ROUNDS
    )
)


if not rookie_rounds:

    rookie_rounds = (
        DEFAULT_ROOKIE_ROUNDS
    )


franchise_ids = sorted(
    int(x)
    for x in (
        latest_owner_name.keys()
    )
)


current_pick_owner = {}


for pick_season in FUTURE_PICK_YEARS:

    for round_num in range(
        1,
        int(
            rookie_rounds
        )
        + 1
    ):

        for original_franchise in franchise_ids:

            current_pick_owner[
                (
                    int(
                        pick_season
                    ),
                    int(
                        round_num
                    ),
                    int(
                        original_franchise
                    )
                )
            ] = int(
                original_franchise
            )


for pick in current_traded_picks_json or []:

    try:

        key = (
            int(
                pick.get(
                    "season"
                )
            ),

            int(
                pick.get(
                    "round"
                )
            ),

            int(
                pick.get(
                    "roster_id"
                )
            )
        )


        current_pick_owner[
            key
        ] = int(
            pick.get(
                "owner_id"
            )
        )

    except:

        pass


current_pick_rows = []


for (
    pick_season,
    round_num,
    original_franchise
), owner_franchise in (
    current_pick_owner.items()
):

    current_pick_rows.append(
        {
            "pick_season":
                pick_season,

            "round":
                round_num,

            "original_franchise_id":
                original_franchise,

            "current_franchise_id":
                owner_franchise,

            "current_owner_name":
                latest_owner_name.get(
                    owner_franchise
                ),

            "pick_label":
                (
                    f"{pick_season} Round {round_num} "
                    f"(orig. F{original_franchise})"
                )
        }
    )


current_future_picks_df = (
    pd.DataFrame(
        current_pick_rows
    )
    .sort_values(
        [
            "current_franchise_id",
            "pick_season",
            "round",
            "original_franchise_id"
        ]
    )
    .reset_index(
        drop=True
    )
)


