def vcheck(
    label,
    condition,
    detail=""
):

    condition = bool(
        condition
    )


    print(
        (
            "PASS"
            if condition
            else "FAIL"
        )
        +
        " | "
        +
        label
        +
        (
            f" | {detail}"
            if detail
            else ""
        )
    )


    if not condition:

        raise AssertionError(
            label
        )


