"""Section 21"""

# ============================================================


# ============================================================
# AUTOMATION EXPORT: STATIC WEBSITE DATA
# ============================================================
OUTPUT_DIR = Path(__file__).resolve().parents[1] / "data"
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

def _records(df):
    if df is None:
        return []
    clean = df.copy()
    clean = clean.replace({np.nan: None})
    return clean.to_dict(orient="records")

# Purpose-built tables that Section 21 previously created.
current_standings_web_df = (
    team_season_master_df[
        team_season_master_df["season"].astype(int) == CURRENT_YEAR
    ].copy()
)
if {"wins","points_for"}.issubset(current_standings_web_df.columns):
    current_standings_web_df = current_standings_web_df.sort_values(
        ["wins","points_for"], ascending=[False,False]
    ).reset_index(drop=True)
    current_standings_web_df["standing_rank"] = np.arange(1, len(current_standings_web_df)+1)

games_played_col = "games" if "games" in team_season_master_df.columns else "games_played"
completed_seasons = (
    team_season_master_df[
        pd.to_numeric(team_season_master_df[games_played_col], errors="coerce") >= 14
    ]["season"].dropna().astype(int).unique().tolist()
)
completed_season_accomplishments_df = season_accomplishments_df[
    season_accomplishments_df["season"].astype(int).isin(completed_seasons)
].copy().reset_index(drop=True)

# Build every completed Sleeper matchup, including consolation games.
_hist = {int(r["season"]): r for r in history_df.to_dict(orient="records")}
_all_game_rows = []
for (season, week, matchup_id), grp in all_matchup_team_rows_df.groupby(["season","week","matchup_id"], dropna=True):
    season_i, week_i = int(season), int(week)
    info = _hist[season_i]
    last = int(info["current_leg"]) if str(info["status"]) == "complete" else max(0, int(info["current_leg"]) - 1)
    if week_i > last or len(grp) != 2:
        continue
    rs = grp.to_dict(orient="records")
    a,b = rs[0],rs[1]
    s1,s2 = float(a.get("points") or 0), float(b.get("points") or 0)
    winner = a if s1 > s2 else b if s2 > s1 else None
    _all_game_rows.append({
        "season": season_i,
        "week": week_i,
        "matchup_id": matchup_id,
        "game_type": "Regular Season" if week_i < int(info["playoff_week_start"]) else "Postseason",
        "franchise_1": int(a["franchise_id"]),
        "owner_1": a.get("owner_name"),
        "score_1": s1,
        "franchise_2": int(b["franchise_id"]),
        "owner_2": b.get("owner_name"),
        "score_2": s2,
        "winner_franchise_id": int(winner["franchise_id"]) if winner else None,
        "winner_name": winner.get("owner_name") if winner else "Tie",
        "margin": abs(s1-s2),
        "combined_points": s1+s2,
    })
all_games_df = pd.DataFrame(_all_game_rows)

# ============================================================
# TEAM RECORDS — TOTAL ALL-PLAY WINS
# All-Play compares each regular-season team score with every
# other team's score for that week; playoffs are not All-Play.
# Therefore the career total is the SAME in the all-time and
# regular-season record views, and absent from playoff records.
# ============================================================
_all_play_record_source = all_play_career_df.copy()
_all_play_record_source["all_play_wins"] = pd.to_numeric(
    _all_play_record_source["all_play_wins"], errors="raise"
)
_all_play_record_source["rank"] = (
    _all_play_record_source["all_play_wins"]
    .rank(method="min", ascending=False)
    .astype(int)
)
_all_play_record_rows = []
for _record_view in ("All-Time Combined", "Regular Season"):
    for _row in _all_play_record_source.itertuples(index=False):
        _all_play_record_rows.append({
            "category": "Total All-Play Wins",
            "scoring_view": _record_view,
            "rank": int(_row.rank),
            "record_holder": _row.owner_name,
            "value": int(_row.all_play_wins),
            "season": None,
            "franchise_id": int(_row.franchise_id),
            "player_id": None,
            "metric": "all_play_wins",
        })
scoring_record_book_df = pd.concat(
    [
        scoring_record_book_df.loc[
            scoring_record_book_df["category"] != "Total All-Play Wins"
        ],
        pd.DataFrame(_all_play_record_rows),
    ],
    ignore_index=True,
)

TABLES = {
    "league_history": history_df,
    "games": games_df,
    "standings_career": standings_career_df,
    "standings_seasons": standings_seasons_df,
    "all_play_career": all_play_career_df,
    "all_play_seasons": all_play_seasons_df,
    "luck_seasons": luck_seasons_df,
    "playoffs": valid_playoff_games_df,
    "playoff_career": playoff_career_df,
    "h2h": h2h_df,
    "rivalries": rivalries_df,
    "streaks": streaks_df,
    "records": scoring_record_book_df,
    "player_game_log": scoring_player_games_df,
    "player_careers": scoring_player_careers_df,
    "player_seasons": scoring_player_seasons_df,
    "franchise_player_career": franchise_player_career_df,
    "franchise_player_season": franchise_player_season_df,
    "franchise_positions": franchise_position_history_df,
    "franchise_player_leaders": franchise_player_leaders_df,
    "draft_picks": draft_picks_df,
    "draft_value": draft_value_df,
    "startup_draft_value": startup_draft_value_df,
    "rookie_draft_value": rookie_draft_value_df,
    "trades": trade_summary_df,
    "trade_sides": trade_sides_df,
    "trade_assets": trade_assets_df,
    "transactions": transactions_df,
    "team_season_master": team_season_master_df,
    "current_standings_web": current_standings_web_df,
    "roster_season_sleeper": roster_season_sleeper_summary_df,
    "single_season_records": single_season_records_df,
    "team_season_top3": team_single_season_top3_df,
    "season_accomplishments": season_accomplishments_df,
    "completed_accomplishments": completed_season_accomplishments_df,
    "weekly_scoring_ranks": weekly_scoring_rank_df,
    "current_roster": current_roster_snapshot_df,
    "current_future_picks": current_future_picks_df,
    "current_team_assets": current_team_asset_summary_df,
    "weekly_full_rosters": weekly_full_roster_df,
    "all_matchup_teams": all_matchup_team_rows_df,
    "website_streaks": website_streaks_df,
    "league_settings": league_settings_archive_df,
    "all_games": all_games_df,
}

for name, df in TABLES.items():
    path = OUTPUT_DIR / f"{name}.json"
    with path.open("w", encoding="utf-8") as f:
        json.dump(_records(df), f, ensure_ascii=False, separators=(",",":"), default=str)
    print(f"WROTE | {name}.json | {len(df):,} rows")

manifest = {name: len(df) for name,df in TABLES.items()}
with (OUTPUT_DIR / "manifest.json").open("w", encoding="utf-8") as f:
    json.dump(manifest, f, indent=2)

print("AUTOMATED SITE DATA BUILD COMPLETE")
